--
-- Name: al_is_accepting(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.al_is_accepting(q_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.al_queries q
    where q.id = q_id
      and private.tool_is_enabled('audience-listening')
      and q.status = 'open'
      and (q.opens_at is null or q.opens_at <= now())
      and (q.closes_at is null or q.closes_at > now())
  );
$$;


--
-- Name: al_owns_open_submission_object(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.al_owns_open_submission_object(object_name text, uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.al_submissions s
    where private.tool_is_enabled('audience-listening')
      and s.participant_user_id = uid
      and s.status = 'in_progress'
      and object_name like s.query_id::text || '/' || s.id::text || '/%'
  );
$$;


--
-- Name: can_open_tool(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_open_tool(uid uuid, p_tool_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.tools t
    join public.profiles p on p.id = uid
    where t.id = p_tool_id
      and t.enabled
      and p.account_status = 'active'
      and (
        t.default_access = 'approved_staff'
        or exists (
          select 1
          from public.tool_access ta
          where ta.tool_id = t.id
            and ta.user_id = uid
            and ta.revoked_at is null
        )
      )
  );
$$;


