--
-- Name: log_is_automated(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.log_is_automated(p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with here as (
    select (p_at at time zone private.station_time_zone())::date as d,
           extract(dow from (p_at at time zone private.station_time_zone()))::integer as dow,
           (p_at at time zone private.station_time_zone())::time as t
  ),
  change as (
    select c.mode
    from public.log_on_air_changes c
    where c.active and p_at >= c.starts_at and p_at < c.ends_at
    limit 1
  )
  select case
    when exists (select 1 from change) then (select mode = 'automated' from change)
    else exists (
      select 1
      from public.log_automated_weekly w, here h
      where w.active
        and (
          -- Same-day window.
          (w.end_time > w.start_time
            and h.dow = any (w.days_of_week)
            and h.t >= w.start_time and h.t < w.end_time
            and w.effective_from <= h.d and (w.effective_to is null or w.effective_to >= h.d))
          -- Past midnight, evening part: today's window.
          or (w.end_time <= w.start_time
            and h.t >= w.start_time
            and h.dow = any (w.days_of_week)
            and w.effective_from <= h.d and (w.effective_to is null or w.effective_to >= h.d))
          -- Past midnight, early-morning part: the window that started yesterday.
          or (w.end_time <= w.start_time
            and h.t < w.end_time
            and ((h.dow + 6) % 7) = any (w.days_of_week)
            and w.effective_from <= h.d - 1 and (w.effective_to is null or w.effective_to >= h.d - 1))
        )
    )
  end;
$$;


--
-- Name: log_is_closed_to_underwriting(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.log_is_closed_to_underwriting(p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with here as (
    select (p_at at time zone private.station_time_zone())::date as d,
           extract(dow from (p_at at time zone private.station_time_zone()))::integer as dow,
           (p_at at time zone private.station_time_zone())::time as t
  ),
  change as (
    select c.mode
    from public.log_underwriting_hour_changes c
    where c.active and p_at >= c.starts_at and p_at < c.ends_at
    limit 1
  )
  select case
    when exists (select 1 from change) then (select mode = 'closed' from change)
    else exists (
      select 1
      from public.log_underwriting_closed_weekly w, here h
      where w.active
        and (
          -- Same-day window.
          (w.end_time > w.start_time
            and h.dow = any (w.days_of_week)
            and h.t >= w.start_time and h.t < w.end_time
            and w.effective_from <= h.d and (w.effective_to is null or w.effective_to >= h.d))
          -- Past midnight, evening part: today's window.
          or (w.end_time <= w.start_time
            and h.t >= w.start_time
            and h.dow = any (w.days_of_week)
            and w.effective_from <= h.d and (w.effective_to is null or w.effective_to >= h.d))
          -- Past midnight, early-morning part: the window that started yesterday.
          or (w.end_time <= w.start_time
            and h.t < w.end_time
            and ((h.dow + 6) % 7) = any (w.days_of_week)
            and w.effective_from <= h.d - 1 and (w.effective_to is null or w.effective_to >= h.d - 1))
        )
    )
  end;
$$;


--
-- Name: rc_release_guide(text, text, text, text, jsonb, text[], integer, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rc_release_guide(p_slug text, p_tool_key text, p_title text, p_summary text, p_body jsonb, p_screen_keys text[], p_sort_order integer, p_version_note text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_tool_id uuid;
  v_existing public.rc_articles%rowtype;
begin
  select id into v_tool_id from public.tools where key = p_tool_key;
  if v_tool_id is null then
    raise exception 'rc_release_guide(%): no tool with key %', p_slug, p_tool_key;
  end if;

  select * into v_existing from public.rc_articles where slug = p_slug;

  if not found then
    insert into public.rc_articles
      (slug, kind, title, summary, body, tool_id, screen_keys, sort_order,
       source, version_note)
    values
      (p_slug, 'guide', p_title, p_summary, p_body, v_tool_id, p_screen_keys,
       p_sort_order, 'release', p_version_note);
    return;
  end if;

  if v_existing.kind <> 'guide' then
    raise exception 'rc_release_guide(%): that slug is a %, not a guide', p_slug, v_existing.kind;
  end if;

  if v_existing.edited_since_release then
    -- An editor changed this guide after the last release wrote it. Their
    -- words win; the release note still ships, and an editor reconciles.
    update public.rc_articles set needs_review = true where id = v_existing.id;
    return;
  end if;

  update public.rc_articles set
    title = p_title,
    summary = p_summary,
    body = p_body,
    tool_id = v_tool_id,
    screen_keys = p_screen_keys,
    sort_order = p_sort_order,
    source = 'release',
    version_note = p_version_note,
    needs_review = false
  where id = v_existing.id;
end;
$$;


--
-- Name: rc_release_note(text, text, date, text, jsonb, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rc_release_note(p_slug text, p_tool_key text, p_released_on date, p_title text, p_body jsonb, p_guide_slugs text[] DEFAULT '{}'::text[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_tool_id uuid;
  v_note_id uuid;
  v_guide_slug text;
  v_guide_id uuid;
begin
  if p_tool_key is not null then
    select id into v_tool_id from public.tools where key = p_tool_key;
    if v_tool_id is null then
      raise exception 'rc_release_note(%): no tool with key %', p_slug, p_tool_key;
    end if;
  end if;

  insert into public.rc_articles
    (slug, kind, title, body, tool_id, released_on, source)
  values
    (p_slug, 'release_note', p_title, p_body, v_tool_id, p_released_on, 'release')
  on conflict (slug) do update set
    title = excluded.title,
    body = excluded.body,
    tool_id = excluded.tool_id,
    released_on = excluded.released_on,
    source = excluded.source
  where public.rc_articles.kind = 'release_note'
  returning id into v_note_id;

  if v_note_id is null then
    raise exception 'rc_release_note(%): that slug is taken by an article that is not a release note', p_slug;
  end if;

  foreach v_guide_slug in array coalesce(p_guide_slugs, '{}') loop
    select id into v_guide_id from public.rc_articles where slug = v_guide_slug and kind = 'guide';
    if v_guide_id is null then
      raise exception 'rc_release_note(%): no guide with slug %', p_slug, v_guide_slug;
    end if;
    insert into public.rc_release_note_guides (release_note_id, guide_id)
    values (v_note_id, v_guide_id)
    on conflict do nothing;
  end loop;
end;
$$;


--
-- Name: ri_host_owns_storage_object(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ri_host_owns_storage_object(object_name text, uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.ri_participants p
    join public.ri_sessions s on s.id = p.session_id
    where object_name like p.storage_prefix || '/%'
      and s.created_by = uid
  );
$$;


