begin
  select s.time_zone into v_zone from public.station_settings s where s.id;
  if v_zone is null then
    raise exception 'public.station_settings has no row; the station time zone is not set.';
  end if;
  return v_zone;
end;
$$;


--
-- Name: tool_is_enabled(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tool_is_enabled(p_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select t.enabled from public.tools t where t.key = p_key), false);
$$;


--
-- Name: uw_next_dad_cut(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.uw_next_dad_cut() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cut text;
begin
  loop
    v_cut := lpad(nextval('public.uw_dad_cut_seq')::text, 5, '0') || 'A';
    exit when not exists (select 1 from public.uw_copy where dad_cut = v_cut);
  end loop;
  return v_cut;
end;
$$;


--
-- Name: uw_reconcile_imported_copy(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.uw_reconcile_imported_copy(p_copy_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_plays boolean;
begin
  select private.uw_script_plays_recording(script) into v_plays
  from public.uw_copy where id = p_copy_id;
  if v_plays is null then
    return;
  end if;

  update public.uw_copy
  set execution_kind = case when v_plays
        then 'recorded'::public.uw_copy_execution_kind
        else 'live_read'::public.uw_copy_execution_kind end,
      dad_cut = case
        when v_plays and dad_cut like '%A' then null
        when not v_plays and (dad_cut is null or dad_cut not like '%A')
          then private.uw_next_dad_cut()
        else dad_cut
      end
  where id = p_copy_id
    and execution_kind is distinct from (case when v_plays
        then 'recorded'::public.uw_copy_execution_kind
        else 'live_read'::public.uw_copy_execution_kind end);
end;
$$;


--
-- Name: uw_script_plays_recording(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.uw_script_plays_recording(p_script text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select coalesce(p_script ~* '\mplease\s+(the\s+)?play\M', false);
$$;


--
-- Name: al_complete_answer(uuid, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.al_complete_answer(p_answer_id uuid, p_size_bytes bigint, p_duration_ms integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_max_seconds integer;
begin
  if auth.uid() is null then
    return jsonb_build_object('error', 'unauthenticated');
  end if;

  select coalesce(q.max_duration_seconds, 600) into v_max_seconds
  from public.al_answers a
  join public.al_submissions s on s.id = a.submission_id
  left join public.al_questions q on q.id = a.question_id
  where a.id = p_answer_id
    and s.participant_user_id = auth.uid()
    and s.status = 'in_progress';
  if not found then
    return jsonb_build_object('error', 'not_open');
  end if;

  -- Matches the bucket's own file_size_limit; both are enforced, independently.
  if p_size_bytes is null or p_size_bytes <= 0 or p_size_bytes > 52428800 then
    return jsonb_build_object('error', 'invalid_size');
  end if;

  -- 10% plus two seconds of tolerance: an encoder finishing its current frame
  -- routinely overshoots a stop() by a little, and rejecting a good answer over
  -- that would be indefensible.
  if p_duration_ms is not null
     and p_duration_ms > (v_max_seconds * 1000 * 11 / 10 + 2000)
  then
    return jsonb_build_object('error', 'too_long');
  end if;

  update public.al_answers
  set status = 'uploaded',
      size_bytes = p_size_bytes,
      duration_ms = p_duration_ms
  where id = p_answer_id;

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: al_enforce_question_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.al_enforce_question_limit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if (select count(*) from public.al_questions where query_id = new.query_id) >= 5 then
    raise exception 'A query can have at most 5 questions.'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


--
-- Name: al_finalize_submission(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.al_finalize_submission(p_submission_id uuid, p_consent_agreed boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sub public.al_submissions;
  v_query public.al_queries;
  v_uploaded integer;
  v_missing integer;
begin
  if auth.uid() is null then
    return jsonb_build_object('error', 'unauthenticated');
  end if;
  if not coalesce(p_consent_agreed, false) then
    return jsonb_build_object('error', 'consent_required');
  end if;

  select * into v_sub
  from public.al_submissions
  where id = p_submission_id
    and participant_user_id = auth.uid()
    and status = 'in_progress';
  if not found then
    return jsonb_build_object('error', 'not_open');
  end if;

  select * into v_query from public.al_queries where id = v_sub.query_id;

  -- Deliberately NOT private.al_is_accepting(): a participant who was already
  -- recording when the query closed is allowed to finish. Their work is not
  -- discarded for a deadline they could not see coming. An archived query is
  -- genuinely over, and a draft can have no submissions at all.
  if v_query.status not in ('open', 'closed') then
    return jsonb_build_object('error', 'not_open');
  end if;

  select count(*) into v_uploaded
  from public.al_answers
  where submission_id = v_sub.id and status = 'uploaded';
  if v_uploaded = 0 then
    return jsonb_build_object('error', 'no_answers');
  end if;

  select count(*) into v_missing
  from public.al_questions q
  where q.query_id = v_sub.query_id
    and q.required
    and not exists (
      select 1 from public.al_answers a
      where a.submission_id = v_sub.id
        and a.question_id = q.id
        and a.status = 'uploaded'
    );
  if v_missing > 0 then
    return jsonb_build_object('error', 'required_answer_missing');
  end if;

  if (v_query.field_name = 'required' and coalesce(v_sub.participant_name, '') = '')
     or (v_query.field_email = 'required' and coalesce(v_sub.participant_email, '') = '')
     or (v_query.field_phone = 'required' and coalesce(v_sub.participant_phone, '') = '')
     or (v_query.field_city = 'required' and coalesce(v_sub.participant_city, '') = '')
     or (v_query.field_note = 'required' and coalesce(v_sub.participant_note, '') = '')
  then
    return jsonb_build_object('error', 'required_field_missing');
  end if;

  update public.al_submissions
  set status = 'submitted',
      submitted_at = now(),
      consent_agreed_at = now()
  where id = v_sub.id;

  -- Never-completed placeholder rows are left alone rather than deleted: their
  -- storage object may well exist, and a 'pending' row is how the review screen
  -- shows "upload incomplete" honestly instead of silently as "skipped".
  if v_query.transcription_mode = 'automatic' then
    update public.al_answers
    set transcription_state = 'queued'
    where submission_id = v_sub.id and status = 'uploaded';
  end if;

  return jsonb_build_object('ok', true, 'answers', v_uploaded);
end;
$$;


--
-- Name: al_participant_progress(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.al_participant_progress(p_submission_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'status', s.status,
    'answers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'answer_id', a.id,
        'question_id', a.question_id,
        'status', a.status,
        'duration_ms', a.duration_ms
      ))
      from public.al_answers a
      where a.submission_id = s.id
    ), '[]'::jsonb)
  )
  from public.al_submissions s
  where s.id = p_submission_id
    and s.participant_user_id = auth.uid();
$$;


--
-- Name: al_public_query(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.al_public_query(p_public_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'public_id', q.public_id,
    'public_title', q.public_title,
    'public_intro', q.public_intro,
    'state', case
      when not private.tool_is_enabled('audience-listening') then 'closed'
      when q.status <> 'open' then 'closed'
      when q.opens_at is not null and q.opens_at > now() then 'not_yet_open'
      when q.closes_at is not null and q.closes_at <= now() then 'closed'
      else 'open'
    end,
    'opens_at', q.opens_at,
    'closes_at', q.closes_at,
    'consent_text', q.consent_text,
    'ask_contact_permission', q.ask_contact_permission,
    'ask_attribution_permission', q.ask_attribution_permission,
    'allow_anonymous_request', q.allow_anonymous_request,
    'fields', jsonb_build_object(
      'name', q.field_name,
      'email', q.field_email,
      'phone', q.field_phone,
      'city', q.field_city,
      'note', q.field_note
    ),
    'questions', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', x.id,
          'position', x.position,
          'prompt', x.prompt,
          'guidance', x.guidance,
          'required', x.required,
          'max_duration_seconds', x.max_duration_seconds
        )
        order by x.position, x.created_at
      )
      from public.al_questions x
      where x.query_id = q.id
    ), '[]'::jsonb)
  )
  from public.al_queries q
  where q.public_id = p_public_id
    and q.status <> 'draft';
$$;


--
-- Name: al_reserve_answer(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.al_reserve_answer(p_submission_id uuid, p_question_id uuid, p_content_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sub public.al_submissions;
  v_question public.al_questions;
  v_answer_id uuid;
  v_path text;
begin
  if auth.uid() is null then
    return jsonb_build_object('error', 'unauthenticated');
  end if;

  -- Keep in step with the bucket's allowed_mime_types above.
  if p_content_type is null
     or p_content_type not in ('audio/webm', 'audio/ogg', 'audio/mp4', 'audio/mpeg', 'audio/wav')
  then
    return jsonb_build_object('error', 'unsupported_type');
  end if;

  select * into v_sub
  from public.al_submissions
  where id = p_submission_id
    and participant_user_id = auth.uid()
    and status = 'in_progress';
  if not found then
    return jsonb_build_object('error', 'not_open');
  end if;

  select * into v_question
  from public.al_questions
  where id = p_question_id and query_id = v_sub.query_id;
  if not found then
    return jsonb_build_object('error', 'unknown_question');
  end if;

  select id into v_answer_id
  from public.al_answers
  where submission_id = v_sub.id and question_id = v_question.id;

  if v_answer_id is null then
    v_answer_id := gen_random_uuid();
    v_path := v_sub.query_id::text || '/' || v_sub.id::text || '/' || v_answer_id::text;
    insert into public.al_answers (
      id, submission_id, query_id, question_id,
      question_prompt, question_position, question_required,
      status, storage_path, content_type
    ) values (
      v_answer_id, v_sub.id, v_sub.query_id, v_question.id,
      v_question.prompt, v_question.position, v_question.required,
      'pending', v_path, p_content_type
    );
  else
    -- A redo. Same row, same object key, re-snapshotted wording (the prompt may
    -- have been edited between the first take and this one).
    update public.al_answers
    set status = 'pending',
        content_type = p_content_type,
        size_bytes = null,
        duration_ms = null,
        question_prompt = v_question.prompt,
        question_position = v_question.position,
        question_required = v_question.required
    where id = v_answer_id
    returning storage_path into v_path;
  end if;

  return jsonb_build_object('answer_id', v_answer_id, 'storage_path', v_path);
end;
$$;


--
-- Name: al_save_participant_details(uuid, text, text, text, text, text, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.al_save_participant_details(p_submission_id uuid, p_name text, p_email text, p_phone text, p_city text, p_note text, p_consent_contact boolean, p_consent_identify boolean, p_request_anonymous boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then
    return jsonb_build_object('error', 'unauthenticated');
  end if;

  update public.al_submissions
  set
    participant_name = nullif(left(trim(coalesce(p_name, '')), 200), ''),
    participant_email = nullif(left(trim(coalesce(p_email, '')), 320), ''),
    participant_phone = nullif(left(trim(coalesce(p_phone, '')), 40), ''),
    participant_city = nullif(left(trim(coalesce(p_city, '')), 200), ''),
    participant_note = nullif(left(trim(coalesce(p_note, '')), 4000), ''),
    consent_contact = coalesce(p_consent_contact, false),
    consent_identify = coalesce(p_consent_identify, false),
    request_anonymous = coalesce(p_request_anonymous, false)
  where id = p_submission_id
    and participant_user_id = auth.uid()
    and status = 'in_progress';

  if not found then
    return jsonb_build_object('error', 'not_open');
  end if;
  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: al_start_submission(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.al_start_submission(p_public_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_query_id uuid;
  v_existing uuid;
  v_total integer;
  v_new_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('error', 'unauthenticated');
  end if;

  select id into v_query_id from public.al_queries where public_id = p_public_id;
  if v_query_id is null or not private.al_is_accepting(v_query_id) then
    return jsonb_build_object('error', 'not_accepting');
  end if;

  select id into v_existing
  from public.al_submissions
  where query_id = v_query_id
    and participant_user_id = auth.uid()
    and status = 'in_progress'
  limit 1;

  if v_existing is not null then
    return jsonb_build_object('submission_id', v_existing, 'resumed', true);
  end if;

  -- One participant, one query, three tries. Enough for someone who genuinely
  -- wants a second go; not enough to be a flood vector. See design doc §6.
  select count(*) into v_total
  from public.al_submissions
  where query_id = v_query_id and participant_user_id = auth.uid();

  if v_total >= 3 then
    return jsonb_build_object('error', 'submission_limit');
  end if;

  insert into public.al_submissions (query_id, participant_user_id)
  values (v_query_id, auth.uid())
  returning id into v_new_id;

  return jsonb_build_object('submission_id', v_new_id, 'resumed', false);
end;
$$;


--
-- Name: ap_public_form_config(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ap_public_form_config() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'is_open', s.is_open and private.tool_is_enabled('academic-partnerships'),
    'intro_copy', s.intro_copy,
    'enabled_partnership_types', s.enabled_partnership_types
  )
  from public.ap_settings s
  where s.id = true;
$$;


--
-- Name: ap_stamp_stage_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ap_stamp_stage_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.stage is distinct from old.stage then
    new.stage_changed_at = now();
    new.stage_changed_by = auth.uid();
  end if;
  return new;
end;
$$;


--
-- Name: ap_submit_inquiry(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ap_submit_inquiry(p_payload jsonb, p_ip_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_settings public.ap_settings;
  v_types public.ap_partnership_type[];
  v_type public.ap_partnership_type;
  v_raw_type text;
  v_email text;
  v_students integer;
  v_recent_by_email integer;
  v_recent_by_ip integer;
  v_new_id uuid;
begin
  select * into v_settings from public.ap_settings where id = true;
  if v_settings.is_open is not true or not private.tool_is_enabled('academic-partnerships') then
    return jsonb_build_object('error', 'closed');
  end if;

  v_types := array[]::public.ap_partnership_type[];
  begin
    for v_raw_type in select jsonb_array_elements_text(coalesce(p_payload->'partnership_types', '[]'::jsonb))
    loop
      v_type := v_raw_type::public.ap_partnership_type;
      if not (v_type = any (v_settings.enabled_partnership_types)) then
        return jsonb_build_object('error', 'invalid_partnership_type');
      end if;
      if not (v_type = any (v_types)) then
        v_types := v_types || v_type;
      end if;
    end loop;
  exception when invalid_text_representation then
    return jsonb_build_object('error', 'invalid_partnership_type');
  end;

  if cardinality(v_types) = 0 then
    return jsonb_build_object('error', 'invalid_partnership_type');
  end if;

  v_email := trim(p_payload->>'email');
  if v_email is null or v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then
    return jsonb_build_object('error', 'invalid_email');
  end if;

  if coalesce(trim(p_payload->>'faculty_name'), '') = ''
     or coalesce(trim(p_payload->>'department'), '') = ''
     or coalesce(trim(p_payload->>'description'), '') = ''
  then
    return jsonb_build_object('error', 'missing_required_field');
  end if;

  if 'faculty_research' = any (v_types)
     and coalesce(trim(p_payload->>'research_topic'), '') = ''
  then
    return jsonb_build_object('error', 'missing_required_field');
  end if;

  begin
    v_students := nullif(trim(p_payload->>'estimated_students_reached'), '')::integer;
  exception when invalid_text_representation then
    return jsonb_build_object('error', 'invalid_estimated_students_reached');
  end;

  -- Bounded per submitter, in the same transaction as the write — the same
  -- shape as al_start_submission's "one participant, one query, three tries",
  -- adapted to having no participant identity: email and a salted IP hash
  -- (computed by the caller, from x-forwarded-for, never the raw IP) are the
  -- two things available. See design doc §3 "Abuse protection".
  select count(*) into v_recent_by_email
  from public.ap_submissions
  where email = v_email and created_at > now() - interval '24 hours';
  if v_recent_by_email >= 3 then
    return jsonb_build_object('error', 'rate_limited');
  end if;

  if p_ip_hash is not null then
    select count(*) into v_recent_by_ip
    from public.ap_submissions
    where submitted_ip_hash = p_ip_hash and created_at > now() - interval '1 hour';
    if v_recent_by_ip >= 5 then
      return jsonb_build_object('error', 'rate_limited');
    end if;
  end if;

  insert into public.ap_submissions (
    faculty_name, email, department, phone, partnership_types,
    course_title, course_number, timeframe, estimated_students_reached,
    description, student_experience, support_requested,
    deliverables, relevant_dates, may_publish, additional_context,
    research_topic, research_relevance, research_status,
    research_availability,
    submitted_ip_hash
  ) values (
    trim(p_payload->>'faculty_name'), v_email, trim(p_payload->>'department'),
    nullif(trim(p_payload->>'phone'), ''), v_types,
    nullif(trim(p_payload->>'course_title'), ''), nullif(trim(p_payload->>'course_number'), ''),
    nullif(trim(p_payload->>'timeframe'), ''),
    v_students,
    trim(p_payload->>'description'),
    nullif(trim(p_payload->>'student_experience'), ''), nullif(trim(p_payload->>'support_requested'), ''),
    nullif(trim(p_payload->>'deliverables'), ''), nullif(trim(p_payload->>'relevant_dates'), ''),
    coalesce((p_payload->>'may_publish')::boolean, false), nullif(trim(p_payload->>'additional_context'), ''),
    nullif(trim(p_payload->>'research_topic'), ''),
    nullif(trim(p_payload->>'research_relevance'), ''), nullif(trim(p_payload->>'research_status'), ''),
    nullif(trim(p_payload->>'research_availability'), ''),
    p_ip_hash
  )
  returning id into v_new_id;

  insert into public.ap_submission_events (submission_id, actor_id, event_type, note)
  values (v_new_id, null, 'received', 'Submitted through the public inquiry form.');

  return jsonb_build_object('ok', true, 'confirmation_copy', v_settings.confirmation_copy);
end;
$_$;


--
-- Name: bk_adopt_version(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_adopt_version(p_version_id uuid, p_destination_index text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_status public.bk_version_status;
begin
  select status into v_status from public.bk_rate_model_versions where id = p_version_id;
  if v_status is null then return jsonb_build_object('error', 'unknown_version'); end if;
  if v_status <> 'submitted' then return jsonb_build_object('error', 'not_submitted'); end if;
  update public.bk_rate_model_versions set status = 'superseded' where status = 'adopted' and id <> p_version_id;
  update public.bk_rate_model_versions set in_use = false where in_use and id <> p_version_id;
  update public.bk_rate_model_versions
     set status = 'adopted', destination_index = coalesce(p_destination_index, destination_index)
   where id = p_version_id;
  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: bk_approve_estimate(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_approve_estimate(p_project_id uuid, p_legacy_rate_delta numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_project public.bk_projects;
  v_confirmed integer;
begin
  select * into v_project from public.bk_projects where id = p_project_id for update;
  if v_project.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if v_project.disposition is not null then return jsonb_build_object('error', 'closed'); end if;
  if v_project.stage <> 'estimate' then return jsonb_build_object('error', 'wrong_stage'); end if;

  update public.bk_bookings
     set status = 'confirmed', expires_at = null
   where project_id = p_project_id and status = 'tentative';
  get diagnostics v_confirmed = row_count;

  update public.bk_projects
     set stage = 'booked', estimate_approved_at = now(), estimate_expires_at = null,
         legacy_rate_delta = coalesce(p_legacy_rate_delta, legacy_rate_delta)
   where id = p_project_id;
  return jsonb_build_object('ok', true, 'confirmed', v_confirmed);
end;
$$;


--
-- Name: bk_attach_reserved_block(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_attach_reserved_block(p_block_id uuid, p_project_id uuid, p_labor jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_block public.bk_reserved_blocks;
  v_agreement public.bk_agreements;
  v_project public.bk_projects;
  v_partner public.bk_partners;
  v_plan public.bk_term_plans;
  v_status public.bk_booking_status;
  v_booking uuid;
  v_row jsonb;
begin
  select * into v_block from public.bk_reserved_blocks where id = p_block_id for update;
  if v_block.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if v_block.released_at is not null then return jsonb_build_object('error', 'released'); end if;
  if v_block.project_id is not null then return jsonb_build_object('error', 'taken'); end if;
  select * into v_agreement from public.bk_agreements where id = v_block.agreement_id;
  if v_agreement.status <> 'active' then return jsonb_build_object('error', 'agreement_not_active'); end if;
  if not public.bk_reserved_block_reserves(v_block, v_agreement.release_deadline_days) then
    return jsonb_build_object('error', 'past_deadline');
  end if;

  select * into v_project from public.bk_projects where id = p_project_id for update;
  if v_project.id is null then return jsonb_build_object('error', 'project_not_found'); end if;
  if v_project.disposition is not null then return jsonb_build_object('error', 'closed'); end if;
  if v_project.partner_id <> v_agreement.partner_id then return jsonb_build_object('error', 'other_partner'); end if;
  if v_project.stage in ('delivered', 'settled') then return jsonb_build_object('error', 'wrong_stage'); end if;
  if v_project.agreement_id is not null and v_project.agreement_id <> v_agreement.id then
    return jsonb_build_object('error', 'other_agreement');
  end if;
  select * into v_partner from public.bk_partners where id = v_project.partner_id;

  select * into v_plan from public.bk_term_plans
  where status = 'active' and v_block.date between starts_on and ends_on;
  if v_plan.id is null then return jsonb_build_object('error', 'no_plan'); end if;

  v_status := case
    when v_project.stage = 'booked' then 'confirmed'::public.bk_booking_status
    when v_project.stage = 'estimate' and v_project.estimate_sent_at is not null then 'tentative'::public.bk_booking_status
    else 'planned'::public.bk_booking_status
  end;

  insert into public.bk_bookings
    (plan_id, project_id, pool_id, date, window_start, window_end, treatment, status, expires_at, label, notes, created_by)
  values (
    v_plan.id, v_project.id, v_block.pool_id, v_block.date, v_block.window_start, v_block.window_end,
    coalesce(v_project.priced_as, 'incremental'), v_status,
    case when v_status = 'tentative' then v_project.estimate_expires_at else null end,
    coalesce(v_partner.name, 'Partner') || ': ' || v_project.title,
    'Reserved block under "' || v_agreement.label || '"', auth.uid()
  ) returning id into v_booking;
  for v_row in select * from jsonb_array_elements(coalesce(p_labor, '[]'::jsonb)) loop
    if (v_row->>'hours')::numeric > 0 then
      insert into public.bk_booking_labor (booking_id, labor_class_id, hours)
      values (v_booking, (v_row->>'labor_class_id')::uuid, (v_row->>'hours')::numeric);
    end if;
  end loop;

  update public.bk_reserved_blocks set project_id = v_project.id, booking_id = v_booking where id = v_block.id;
  if v_project.agreement_id is null then
    update public.bk_projects set agreement_id = v_agreement.id where id = v_project.id;
  end if;
  return jsonb_build_object('ok', true, 'booking_id', v_booking, 'status', v_status::text);
end;
$$;


--
-- Name: bk_booking_allowed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_booking_allowed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_plan public.bk_term_plans;
  v_resource public.bk_term_resources;
  v_blackout public.bk_blackouts;
  v_hold public.bk_holds;
  v_taken integer;
  v_class uuid;
  v_partner uuid;
  v_block record;
begin
  if new.status = 'released' then
    new.released_at := coalesce(new.released_at, now());
    return new;
  end if;
  new.released_at := null;

  -- A planned date (a project's, before its estimate is sent) is not a hold:
  -- it takes nothing, so nothing is checked. The screen runs the rule for it.
  if new.status = 'planned' then
    new.expires_at := null;
    return new;
  end if;

  -- An update that leaves a live booking where it is (confirming it, a label
  -- edit) is not re-checked: a later hold must not refuse to confirm a hold
  -- the estimate already placed. A planned date being sent, or an expired
  -- hold being revived, was not live and is checked.
  if tg_op = 'UPDATE'
     and public.bk_booking_is_live(old)
     and (new.plan_id, new.pool_id, new.date, new.window_start, new.window_end, new.treatment)
         is not distinct from
         (old.plan_id, old.pool_id, old.date, old.window_start, old.window_end, old.treatment) then
    return new;
  end if;

  select * into v_plan from public.bk_term_plans where id = new.plan_id;
  if v_plan.id is null then
    raise exception 'That term plan no longer exists.' using errcode = 'check_violation';
  end if;
  if v_plan.status = 'closed' then
    raise exception 'The term plan "%" is closed and final; nothing new books into it.', v_plan.label
      using errcode = 'check_violation';
  end if;
  if new.date < v_plan.starts_on or new.date > v_plan.ends_on then
    raise exception 'The date is outside the term plan (% to %).', v_plan.starts_on, v_plan.ends_on
      using errcode = 'check_violation';
  end if;
  select * into v_resource from public.bk_term_resources r where r.plan_id = new.plan_id and r.pool_id = new.pool_id;
  if v_resource.id is null then
    raise exception 'The term plan has no resource for that pool.' using errcode = 'check_violation';
  end if;

  if new.exception_reason is not null then
    if not private.is_bookings_executive(auth.uid()) then
      raise exception 'Only the Executive Director can record a booking-rule exception.'
        using errcode = 'check_violation';
    end if;
    new.exception_by := coalesce(new.exception_by, auth.uid());
    return new;
  end if;
  new.exception_by := null;

  -- 1. Blacked out?
  select * into v_blackout from public.bk_blackouts b
  where b.plan_id = new.plan_id and new.date between b.starts_on and b.ends_on
    and (b.pool_ids is null or new.pool_id = any (b.pool_ids))
  order by b.starts_on limit 1;
  if v_blackout.id is not null then
    raise exception 'Blacked out: % (% to %).', v_blackout.reason, v_blackout.starts_on, v_blackout.ends_on
      using errcode = 'check_violation';
  end if;

  -- 2. Reserved for another partner? A block an active agreement still holds
  -- on an overlapping window, for a partner other than this booking's, takes
  -- one of the window's units until its release deadline.
  if new.project_id is not null then
    select partner_id into v_partner from public.bk_projects where id = new.project_id;
  end if;
  select rb.id, rb.date, a.release_deadline_days, a.label as agreement_label, p.name as partner_name
    into v_block
  from public.bk_reserved_blocks rb
  join public.bk_agreements a on a.id = rb.agreement_id
  join public.bk_partners p on p.id = a.partner_id
  where a.status = 'active'
    and rb.pool_id = new.pool_id and rb.date = new.date
    and rb.window_start < new.window_end and rb.window_end > new.window_start
    and public.bk_reserved_block_reserves(rb, a.release_deadline_days)
    and (v_partner is null or a.partner_id <> v_partner)
    and (rb.booking_id is null or rb.booking_id <> new.id)
  order by rb.window_start limit 1;

  -- 1, 2 and 3. The window's concurrent units: holds, live bookings and reserving blocks that overlap.
  select count(*) into v_taken from (
    select 1 from public.bk_holds h
    where h.plan_id = new.plan_id and h.pool_id = new.pool_id and h.date = new.date
      and h.window_start < new.window_end and h.window_end > new.window_start
    union all
    select 1 from public.bk_bookings o
    where o.plan_id = new.plan_id and o.id <> new.id and o.pool_id = new.pool_id and o.date = new.date
      and public.bk_booking_is_live(o)
      and o.window_start < new.window_end and o.window_end > new.window_start
    union all
    select 1 from public.bk_reserved_blocks rb
    join public.bk_agreements a on a.id = rb.agreement_id
    where a.status = 'active'
      and rb.pool_id = new.pool_id and rb.date = new.date
      and rb.window_start < new.window_end and rb.window_end > new.window_start
      and public.bk_reserved_block_reserves(rb, a.release_deadline_days)
      and (v_partner is null or a.partner_id <> v_partner)
      -- A block that already has its own live booking is counted once, as that booking.
      and (rb.booking_id is null or not exists (
            select 1 from public.bk_bookings ob where ob.id = rb.booking_id and public.bk_booking_is_live(ob)))
      and (rb.booking_id is null or rb.booking_id <> new.id)
  ) taken;
  if v_taken >= v_resource.concurrent_units then
    if v_block.id is not null then
      raise exception 'Reserved for % under "%" until % (its release deadline).',
        v_block.partner_name, v_block.agreement_label,
        v_block.date - greatest(v_block.release_deadline_days, 0)
        using errcode = 'check_violation';
    end if;
    select * into v_hold from public.bk_holds h
    where h.plan_id = new.plan_id and h.pool_id = new.pool_id and h.date = new.date
      and h.window_start < new.window_end and h.window_end > new.window_start
    order by h.window_start limit 1;
    if v_hold.id is not null and v_resource.concurrent_units = 1 then
      raise exception 'Held for WUWF on %: % (% to %).', new.date, v_hold.label, v_hold.window_start, v_hold.window_end
        using errcode = 'check_violation';
    end if;
    raise exception 'The window on % is taken: % of % on this pool already booked or held.',
      new.date, v_taken, v_resource.concurrent_units
      using errcode = 'check_violation';
  end if;

  -- A moved, sent or revived booking re-checks its labor rows.
  if tg_op = 'UPDATE' then
    for v_class in select labor_class_id from public.bk_booking_labor where booking_id = new.id loop
      perform public.bk_check_booking_labor(new.id, v_class);
    end loop;
  end if;
  return new;
end;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: bk_bookings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bk_bookings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_id uuid NOT NULL,
    project_id uuid,
    pool_id uuid NOT NULL,
    date date NOT NULL,
    window_start time without time zone NOT NULL,
    window_end time without time zone NOT NULL,
    units numeric(6,2) DEFAULT 1 NOT NULL,
    treatment public.bk_pricing_treatment NOT NULL,
    status public.bk_booking_status DEFAULT 'tentative'::public.bk_booking_status NOT NULL,
    expires_at timestamp with time zone,
    released_at timestamp with time zone,
    label text NOT NULL,
    notes text,
    exception_by uuid,
    exception_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT bk_bookings_exception_pair CHECK (((exception_by IS NULL) = (exception_reason IS NULL))),
    CONSTRAINT bk_bookings_units_positive CHECK ((units > (0)::numeric)),
    CONSTRAINT bk_bookings_window CHECK ((window_end > window_start))
);


--
-- Name: bk_booking_is_live(public.bk_bookings); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_booking_is_live(b public.bk_bookings) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  -- status::text so this body parses in the same transaction that added 'planned'.
  select b.status::text not in ('released', 'planned')
     and (b.status::text <> 'tentative' or b.expires_at is null or b.expires_at > now());
$$;


--
-- Name: bk_booking_labor_allowed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_booking_labor_allowed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  perform public.bk_check_booking_labor(new.booking_id, new.labor_class_id);
  return new;
end;
$$;


--
-- Name: bk_check_booking_labor(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_check_booking_labor(p_booking_id uuid, p_labor_class_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_booking public.bk_bookings;
  v_capacity public.bk_term_capacity;
  v_class text;
  v_day_hours numeric;
  v_day_cap numeric;
  v_has_reserve boolean;
  v_reserve numeric;
  v_strategic numeric;
  v_nonstrategic numeric;
  v_held numeric;
  v_open numeric;
begin
  select * into v_booking from public.bk_bookings where id = p_booking_id;
  if v_booking.id is null or not public.bk_booking_is_live(v_booking) or v_booking.exception_reason is not null then
    return;
  end if;
  select * into v_capacity from public.bk_term_capacity
   where plan_id = v_booking.plan_id and labor_class_id = p_labor_class_id;
  if v_capacity.id is null then
    return; -- a class the term plan does not track is not capacity-checked
  end if;
  select name into v_class from public.bk_labor_classes where id = p_labor_class_id;

  -- 4. Room in the class's day (headcount × hours a day), counting this booking.
  select coalesce(sum(hours), 0) into v_day_hours
  from (
    select bl.hours
    from public.bk_booking_labor bl
    join public.bk_bookings b on b.id = bl.booking_id
    where b.plan_id = v_booking.plan_id and b.date = v_booking.date
      and bl.labor_class_id = p_labor_class_id
      and public.bk_booking_is_live(b) and b.exception_reason is null
    union all
    select hl.hours
    from public.bk_hold_labor hl
    join public.bk_holds h on h.id = hl.hold_id
    where h.plan_id = v_booking.plan_id and h.date = v_booking.date and hl.labor_class_id = p_labor_class_id
  ) day;
  v_day_cap := v_capacity.headcount * v_capacity.hours_per_person_day;
  if v_day_hours > v_day_cap then
    raise exception '% on %: % of % hours are already spoken for, so this does not fit the day.',
      v_class, v_booking.date, v_day_hours, v_day_cap
      using errcode = 'check_violation';
  end if;

  -- 5. Capacity for the pricing, counting this booking. Only a class with a share has
  -- a reserve; without one a strategic booking draws open capacity like any other.
  v_has_reserve := v_capacity.reserve_share is not null;
  v_reserve := case when v_has_reserve then v_capacity.net_hours * v_capacity.reserve_share else 0 end;
  select
    coalesce(sum(bl.hours) filter (where v_has_reserve and b.treatment = 'strategic'), 0),
    coalesce(sum(bl.hours) filter (where not (v_has_reserve and b.treatment = 'strategic')), 0)
  into v_strategic, v_nonstrategic
  from public.bk_booking_labor bl
  join public.bk_bookings b on b.id = bl.booking_id
  where b.plan_id = v_booking.plan_id and bl.labor_class_id = p_labor_class_id
    and public.bk_booking_is_live(b) and b.exception_reason is null;
  select coalesce(sum(hl.hours), 0) into v_held
  from public.bk_hold_labor hl
  join public.bk_holds h on h.id = hl.hold_id
  where h.plan_id = v_booking.plan_id and hl.labor_class_id = p_labor_class_id;

  if v_booking.treatment = 'strategic' and v_has_reserve then
    if v_strategic > v_reserve then
      raise exception 'The % reserve (% of % hours) cannot take this strategic booking; % hours would be drawn.',
        v_class, v_reserve, v_capacity.net_hours, v_strategic
        using errcode = 'check_violation';
    end if;
  else
    v_open := v_capacity.net_hours - v_reserve - v_held - v_nonstrategic;
    if v_open < 0 then
      raise exception 'Open % capacity is short by % hours for this % booking.',
        v_class, -v_open, v_booking.treatment
        using errcode = 'check_violation';
    end if;
  end if;
end;
$$;


--
-- Name: bk_create_booking(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_create_booking(p_booking jsonb, p_labor jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_row jsonb;
begin
  insert into public.bk_bookings
    (plan_id, project_id, pool_id, date, window_start, window_end, units, treatment, status, expires_at,
     label, notes, exception_reason, exception_by, created_by)
  values (
    (p_booking->>'plan_id')::uuid, nullif(p_booking->>'project_id', '')::uuid, (p_booking->>'pool_id')::uuid,
    (p_booking->>'date')::date, (p_booking->>'window_start')::time, (p_booking->>'window_end')::time,
    coalesce((p_booking->>'units')::numeric, 1), (p_booking->>'treatment')::public.bk_pricing_treatment,
    coalesce((p_booking->>'status')::public.bk_booking_status, 'tentative'),
    nullif(p_booking->>'expires_at', '')::timestamptz, p_booking->>'label', p_booking->>'notes',
    nullif(p_booking->>'exception_reason', ''),
    case when nullif(p_booking->>'exception_reason', '') is null then null else auth.uid() end,
    auth.uid()
  ) returning id into v_id;
  for v_row in select * from jsonb_array_elements(coalesce(p_labor, '[]'::jsonb)) loop
    if (v_row->>'hours')::numeric > 0 then
      insert into public.bk_booking_labor (booking_id, labor_class_id, hours)
      values (v_id, (v_row->>'labor_class_id')::uuid, (v_row->>'hours')::numeric);
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;


--
-- Name: bk_create_hold(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_create_hold(p_hold jsonb, p_labor jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_row jsonb;
begin
  insert into public.bk_holds (plan_id, pool_id, date, window_start, window_end, kind, label, created_by)
  values (
    (p_hold->>'plan_id')::uuid, nullif(p_hold->>'pool_id', '')::uuid, (p_hold->>'date')::date,
    (p_hold->>'window_start')::time, (p_hold->>'window_end')::time,
    coalesce((p_hold->>'kind')::public.bk_hold_kind, 'core'), p_hold->>'label', auth.uid()
  ) returning id into v_id;
  for v_row in select * from jsonb_array_elements(coalesce(p_labor, '[]'::jsonb)) loop
    if (v_row->>'hours')::numeric > 0 then
      insert into public.bk_hold_labor (hold_id, labor_class_id, hours)
      values (v_id, (v_row->>'labor_class_id')::uuid, (v_row->>'hours')::numeric);
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;


--
-- Name: bk_guard_agreement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_guard_agreement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.status is distinct from old.status then
    if new.status = 'active' then
      if old.status <> 'draft' then
        raise exception 'An ended agreement is not reopened; draft a new one.' using errcode = 'check_violation';
      end if;
      if not private.is_bookings_executive(auth.uid()) then
        raise exception 'Only the Executive Director approves an agreement.' using errcode = 'check_violation';
      end if;
      new.approved_by := coalesce(new.approved_by, auth.uid());
      new.approved_at := coalesce(new.approved_at, now());
    elsif new.status = 'ended' then
      if not (private.is_bookings_director(auth.uid()) or private.is_bookings_executive(auth.uid())) then
        raise exception 'Only the Director of Operations or the Executive Director ends an agreement.'
          using errcode = 'check_violation';
      end if;
      new.ended_at := coalesce(new.ended_at, now());
    elsif new.status = 'draft' then
      raise exception 'An approved agreement does not go back to draft.' using errcode = 'check_violation';
    end if;
  end if;

  -- The executive approved these terms; only the executive changes them afterwards.
  if old.status <> 'draft'
     and (new.starts_on, new.ends_on, new.reserve_hours_allocated, new.funded_student_hours,
          new.booking_deadline_days, new.release_deadline_days, new.airtime_minutes_per_week)
         is distinct from
         (old.starts_on, old.ends_on, old.reserve_hours_allocated, old.funded_student_hours,
          old.booking_deadline_days, old.release_deadline_days, old.airtime_minutes_per_week)
     and not private.is_bookings_executive(auth.uid()) then
    raise exception 'The terms of an approved agreement change only with the Executive Director.'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


--
-- Name: bk_guard_closed_plan_children(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_guard_closed_plan_children() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_plan_id uuid := case when tg_op = 'DELETE' then old.plan_id else new.plan_id end;
begin
  if exists (select 1 from public.bk_term_plans where id = v_plan_id and status = 'closed') then
    raise exception 'A closed term plan is final. Add a new term plan instead.'
      using errcode = 'check_violation';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


--
-- Name: bk_guard_frozen_assumption_asset(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_guard_frozen_assumption_asset() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_status public.bk_version_status;
begin
  select v.status into v_status
  from public.bk_assumptions a
  join public.bk_rate_model_versions v on v.id = a.version_id
  where a.id = coalesce(new.assumption_id, old.assumption_id);
  if v_status in ('adopted', 'superseded') then
    raise exception 'Rate model version is adopted; a correction is a new version.'
      using errcode = 'check_violation';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


--
-- Name: bk_guard_frozen_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_guard_frozen_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_version uuid;
  v_status public.bk_version_status;
begin
  if tg_table_name in ('bk_package_labor', 'bk_package_resources') then
    select p.version_id into v_version
    from public.bk_service_packages p
    where p.id = coalesce(new.package_id, old.package_id);
  else
    v_version := coalesce(new.version_id, old.version_id);
  end if;
  select status into v_status from public.bk_rate_model_versions where id = v_version;
  if v_status in ('adopted', 'superseded') then
    raise exception 'Rate model version is adopted; a correction is a new version.'
      using errcode = 'check_violation';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


--
-- Name: bk_guard_project(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_guard_project() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_partner uuid;
begin
  -- Settling is Finance's (§6.1); the stage is reached in slice 6, the rule holds from now.
  if new.stage = 'settled' and old.stage is distinct from 'settled'
     and not private.is_bookings_finance(auth.uid()) then
    raise exception 'Only Finance can mark a project settled.' using errcode = 'check_violation';
  end if;

  -- A pricing override that touches the reserve needs the executive (§2.2).
  if new.pricing_overridden_by is not null
     and new.priced_as = 'strategic'
     and (old.priced_as is distinct from 'strategic' or old.pricing_overridden_by is null)
     and not private.is_bookings_executive(auth.uid()) then
    raise exception 'Only the Executive Director can price a project as strategic against its derived treatment.'
      using errcode = 'check_violation';
  end if;

  -- An agreement is the project's partner's (slice 5).
  if new.agreement_id is not null
     and (new.agreement_id is distinct from old.agreement_id or new.partner_id is distinct from old.partner_id) then
    select partner_id into v_partner from public.bk_agreements where id = new.agreement_id;
    if v_partner is distinct from new.partner_id then
      raise exception 'That agreement belongs to another partner.' using errcode = 'check_violation';
    end if;
  end if;

  -- A disposition records who and when; clearing it clears both.
  if new.disposition is not null and old.disposition is distinct from new.disposition then
    new.disposition_by := coalesce(new.disposition_by, auth.uid());
    new.disposition_at := coalesce(new.disposition_at, now());
  elsif new.disposition is null then
    new.disposition_by := null;
    new.disposition_at := null;
    new.disposition_reason := null;
  end if;

  if new.stage = 'delivered' and old.stage is distinct from 'delivered' then
    new.delivered_at := coalesce(new.delivered_at, now());
  end if;
  return new;
end;
$$;


--
-- Name: bk_guard_project_settled(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_guard_project_settled() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.stage = 'settled' and old.stage is distinct from 'settled'
     and not exists (
       select 1 from public.bk_settlements s where s.project_id = new.id and s.status = 'posted'
     ) then
    raise exception 'A project is settled by posting its settlement.' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


--
-- Name: bk_guard_reserved_block(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_guard_reserved_block() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_agreement public.bk_agreements;
  v_partner uuid;
begin
  select * into v_agreement from public.bk_agreements where id = new.agreement_id;
  if v_agreement.id is null then
    raise exception 'That agreement no longer exists.' using errcode = 'check_violation';
  end if;
  if tg_op = 'INSERT' and v_agreement.status = 'ended' then
    raise exception 'An ended agreement takes no new reserved blocks.' using errcode = 'check_violation';
  end if;
  if new.date < v_agreement.starts_on or new.date > v_agreement.ends_on then
    raise exception 'The block is outside the agreement (% to %).', v_agreement.starts_on, v_agreement.ends_on
      using errcode = 'check_violation';
  end if;

  -- Keeping a block is the director's (§6.1).
  if new.kept_by is not null and (tg_op = 'INSERT' or old.kept_by is null) then
    if not (private.is_bookings_director(auth.uid()) or private.is_bookings_executive(auth.uid())) then
      raise exception 'Only the Director of Operations keeps a reserved block past its deadline.'
        using errcode = 'check_violation';
    end if;
    new.kept_at := coalesce(new.kept_at, now());
  elsif new.kept_by is null then
    new.kept_at := null;
  end if;

  -- The project that takes a block is the agreement's partner's.
  if new.project_id is not null then
    select partner_id into v_partner from public.bk_projects where id = new.project_id;
    if v_partner is distinct from v_agreement.partner_id then
      raise exception 'The block belongs to another partner''s agreement.' using errcode = 'check_violation';
    end if;
  else
    new.booking_id := null;
  end if;
  return new;
end;
$$;


--
-- Name: bk_guard_settlement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_guard_settlement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_project public.bk_projects;
begin
  if tg_op = 'INSERT' then
    select * into v_project from public.bk_projects where id = new.project_id;
    if v_project.id is null or v_project.stage <> 'delivered' or v_project.disposition is not null then
      raise exception 'A settlement is drafted for a delivered project.' using errcode = 'check_violation';
    end if;
    if new.status <> 'drafted' then
      raise exception 'A settlement is drafted first; posting is a separate step.' using errcode = 'check_violation';
    end if;
    new.drafted_by := coalesce(new.drafted_by, auth.uid());
    return new;
  end if;

  if old.status = 'posted' then
    raise exception 'A posted settlement is final; a correction is a note on the project.' using errcode = 'check_violation';
  end if;
  if new.project_id is distinct from old.project_id then
    raise exception 'A settlement stays with its project.' using errcode = 'check_violation';
  end if;
  if new.status = 'posted' then
    if not private.is_bookings_finance(auth.uid()) then
      raise exception 'Only Finance can post a settlement.' using errcode = 'check_violation';
    end if;
    new.posted_at := coalesce(new.posted_at, now());
    new.posted_by := coalesce(new.posted_by, auth.uid());
  end if;
  return new;
end;
$$;


--
-- Name: bk_guard_term_plan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_guard_term_plan() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_other public.bk_term_plans;
begin
  if tg_op = 'UPDATE' and old.status = 'closed' then
    -- Only the notes of a closed term may change; the figures it was judged by may not.
    if (new.status, new.label, new.starts_on, new.ends_on, new.airtime_contributed_minutes_per_week)
       is distinct from
       (old.status, old.label, old.starts_on, old.ends_on, old.airtime_contributed_minutes_per_week) then
      raise exception 'A closed term plan is final. Add a new term plan instead.'
        using errcode = 'check_violation';
    end if;
    return new;
  end if;

  -- Several plans may be active together, but a date must belong to only one.
  if new.status = 'active' then
    select * into v_other from public.bk_term_plans p
    where p.id <> new.id and p.status = 'active'
      and p.starts_on <= new.ends_on and new.starts_on <= p.ends_on
    limit 1;
    if v_other.id is not null then
      raise exception 'Another active term plan, "%", overlaps these dates (% to %). Change its dates or close it first.',
        v_other.label, v_other.starts_on, v_other.ends_on
        using errcode = 'check_violation';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: bk_guard_version_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_guard_version_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_pending integer;
begin
  if new.status is distinct from old.status then
    if old.status = 'draft' and new.status = 'submitted' then
      select count(*) into v_pending
      from (
        select 1 from public.bk_assumptions a where a.version_id = new.id and a.validation_state = 'pending'
        union all
        select 1 from public.bk_resource_pools r where r.version_id = new.id and r.validation_state = 'pending'
        union all
        select 1 from public.bk_labor_rates l where l.version_id = new.id and l.validation_state = 'pending'
      ) pending;
      if v_pending > 0 then
        raise exception 'This version still has % input(s) awaiting validation.', v_pending
          using errcode = 'check_violation';
      end if;
      new.submitted_at := coalesce(new.submitted_at, now());
      new.submitted_by := coalesce(new.submitted_by, auth.uid());
    elsif old.status = 'submitted' and new.status = 'draft' then
      new.submitted_at := null;
      new.submitted_by := null;
    elsif old.status = 'submitted' and new.status = 'adopted' then
      if not private.is_bookings_executive(auth.uid()) then
        raise exception 'Only the Executive Director can adopt a rate card version.'
          using errcode = 'check_violation';
      end if;
      new.adopted_at := coalesce(new.adopted_at, now());
      new.adopted_by := coalesce(new.adopted_by, auth.uid());
      new.in_use := true;
    elsif old.status = 'adopted' and new.status = 'superseded' then
      if not private.is_bookings_executive(auth.uid()) then
        raise exception 'Only the Executive Director can supersede an adopted rate card version.'
          using errcode = 'check_violation';
      end if;
      new.superseded_at := coalesce(new.superseded_at, now());
      new.in_use := false;
    else
      raise exception 'A rate model version cannot move from % to %.', old.status, new.status
        using errcode = 'check_violation';
    end if;
  elsif old.status in ('adopted', 'superseded') then
    if (new.label, new.notes, new.destination_index)
         is distinct from (old.label, old.notes, old.destination_index) then
      raise exception 'An adopted rate model version cannot be edited; a correction is a new version.'
        using errcode = 'check_violation';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: bk_institutional_airtime_honored(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_institutional_airtime_honored(p_plan_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_plan public.bk_term_plans;
  v_as_of date;
  v_rows jsonb;
begin
  if auth.uid() is null or not private.has_bookings_access(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;
  select * into v_plan from public.bk_term_plans where id = p_plan_id;
  if v_plan.id is null then
    return jsonb_build_object('error', 'not_found');
  end if;
  v_as_of := least(greatest(v_plan.starts_on, current_date), v_plan.ends_on);

  with commitments as (
    select c.*
    from public.bk_airtime_commitments c
    where c.honored_in <> 'pending'
      and c.starts_on <= v_plan.ends_on
      and (c.ends_on is null or c.ends_on >= v_plan.starts_on)
  ),
  traffic as (
    select c.id as commitment_id,
           ct.id as contract_id,
           ct.status::text as contract_status,
           u.name as underwriter_name,
           (select count(*) from public.uw_scheduled_placements sp
             join public.uw_contract_schedule_lines sl on sl.id = sp.schedule_line_id
            where sl.contract_id = ct.id
              and sp.status::text <> 'superseded'
              and sp.placement_date between v_plan.starts_on and v_plan.ends_on) as placements,
           (select coalesce(sum(sl.duration_seconds), 0) from public.uw_scheduled_placements sp
             join public.uw_contract_schedule_lines sl on sl.id = sp.schedule_line_id
            where sl.contract_id = ct.id
              and sp.status::text <> 'superseded'
              and sp.placement_date between v_plan.starts_on and v_plan.ends_on) as seconds
    from commitments c
    join public.uw_contracts ct on ct.id = c.external_ref
    join public.uw_underwriters u on u.id = ct.underwriter_id
    where c.honored_in = 'traffic'
      and private.tool_is_enabled('underwriting')
  ),
  pins as (
    select c.id as commitment_id,
           a.id as assignment_id,
           a.active,
           ci.title as content_title,
           coalesce(
             nullif((select sum(cc.duration_seconds) from public.log_content_components cc
                      where cc.content_item_id = ci.id and cc.required), 0),
             ci.expected_duration_seconds, 0) as seconds,
           (select coalesce(sum(
               (case when a.hour_index is null then ceil(s.duration_minutes / 60.0)::integer else 1 end)
               * (case when cardinality(a.days_of_week) = 0
                       then (case when cardinality(s.days_of_week) = 0 then 7 else cardinality(s.days_of_week) end)
                       else (select count(*) from unnest(a.days_of_week) d
                              where cardinality(s.days_of_week) = 0 or d = any (s.days_of_week)) end)), 0)
              from public.log_schedule s
              join public.log_clock_versions v on v.clock_template_id = s.clock_template_id
             where v.id = o.clock_version_id
               and s.entry_type = 'recurring'
               and s.start_date <= v_as_of and (s.end_date is null or s.end_date >= v_as_of)
               and v.effective_from <= v_as_of and (v.effective_to is null or v.effective_to >= v_as_of)
           ) as airings_per_week
    from commitments c
    join public.log_opportunity_assignments a on a.id = c.external_ref
    join public.log_local_opportunities o on o.id = a.local_opportunity_id
    join public.log_content_items ci on ci.id = a.content_item_id
    where c.honored_in = 'on_air'
      and private.tool_is_enabled('log')
  )
  select coalesce(jsonb_agg(row_json order by commitment_id), '[]'::jsonb) into v_rows
  from (
    select t.commitment_id, jsonb_build_object(
      'commitment_id', t.commitment_id, 'honored_in', 'traffic', 'found', true,
      'label', case when private.has_underwriting_access(auth.uid()) then t.underwriter_name else 'Traffic contract' end, 'status', t.contract_status,
      'placements_in_term', t.placements, 'seconds_in_term', t.seconds) as row_json
    from traffic t
    union all
    select p.commitment_id, jsonb_build_object(
      'commitment_id', p.commitment_id, 'honored_in', 'on_air', 'found', true,
      'label', case when private.has_log_access(auth.uid()) then p.content_title else 'On Air placement' end, 'status', case when p.active then 'active' else 'inactive' end,
      'airings_per_week', p.airings_per_week, 'seconds', p.seconds) as row_json
    from pins p
    union all
    select c.id, jsonb_build_object(
      'commitment_id', c.id, 'honored_in', c.honored_in::text, 'found', false) as row_json
    from commitments c
    where not exists (select 1 from traffic t where t.commitment_id = c.id)
      and not exists (select 1 from pins p where p.commitment_id = c.id)
  ) rows;

  return jsonb_build_object('ok', true, 'as_of', v_as_of, 'commitments', v_rows);
end;
$$;


--
-- Name: bk_post_settlement(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_post_settlement(p_settlement_id uuid, p_journal_entry_number text, p_funding_index text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_settlement public.bk_settlements;
  v_project public.bk_projects;
  v_index text := nullif(btrim(coalesce(p_funding_index, '')), '');
begin
  if p_journal_entry_number is null or length(btrim(p_journal_entry_number)) = 0 then
    return jsonb_build_object('error', 'journal_entry_required');
  end if;
  select * into v_settlement from public.bk_settlements where id = p_settlement_id for update;
  if v_settlement.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if v_settlement.status = 'posted' then return jsonb_build_object('error', 'already_posted'); end if;
  select * into v_project from public.bk_projects where id = v_settlement.project_id for update;
  if v_project.stage <> 'delivered' or v_project.disposition is not null then
    return jsonb_build_object('error', 'wrong_stage');
  end if;
  v_index := coalesce(v_index, v_settlement.funding_index);
  if v_settlement.kind = 'recharge' and v_index is null then
    return jsonb_build_object('error', 'funding_index_required');
  end if;

  update public.bk_settlements
     set status = 'posted', journal_entry_number = btrim(p_journal_entry_number), funding_index = v_index
   where id = p_settlement_id;
  update public.bk_projects set stage = 'settled' where id = v_settlement.project_id;
  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: bk_public_form_config(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_public_form_config() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'is_open', s.is_open and private.tool_is_enabled('bookings'),
    'intro_copy', s.intro_copy,
    'closed_copy', s.closed_copy,
    'offered_packages', to_jsonb(s.offered_packages)
  )
  from public.bk_settings s
  where s.id = true;
$$;


--
-- Name: bk_reserved_blocks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bk_reserved_blocks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    agreement_id uuid NOT NULL,
    pool_id uuid NOT NULL,
    date date NOT NULL,
    window_start time without time zone NOT NULL,
    window_end time without time zone NOT NULL,
    project_id uuid,
    booking_id uuid,
    released_at timestamp with time zone,
    kept_by uuid,
    kept_at timestamp with time zone,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT bk_reserved_blocks_booking_needs_project CHECK (((booking_id IS NULL) OR (project_id IS NOT NULL))),
    CONSTRAINT bk_reserved_blocks_kept_pair CHECK (((kept_by IS NULL) = (kept_at IS NULL))),
    CONSTRAINT bk_reserved_blocks_window CHECK ((window_end > window_start))
);


--
-- Name: bk_reserved_block_reserves(public.bk_reserved_blocks, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_reserved_block_reserves(b public.bk_reserved_blocks, p_release_deadline_days integer) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select b.released_at is null
     and (b.project_id is not null
          or b.kept_by is not null
          or public.bk_station_today() <= b.date - greatest(p_release_deadline_days, 0));
$$;


--
-- Name: bk_save_package(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_save_package(p_package jsonb, p_labor jsonb, p_resources jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := nullif(p_package->>'id', '')::uuid;
  v_row jsonb;
begin
  if v_id is null then
    insert into public.bk_service_packages
      (version_id, name, unit_label, market_floor, historical_reference, application_note, notes, sort_order, agreement_id)
    values (
      (p_package->>'version_id')::uuid, p_package->>'name', p_package->>'unit_label',
      coalesce((p_package->>'market_floor')::numeric, 0), p_package->>'historical_reference',
      p_package->>'application_note', p_package->>'notes', coalesce((p_package->>'sort_order')::integer, 1000),
      nullif(p_package->>'agreement_id', '')::uuid
    ) returning id into v_id;
  else
    update public.bk_service_packages
       set name = p_package->>'name', unit_label = p_package->>'unit_label',
           market_floor = coalesce((p_package->>'market_floor')::numeric, 0),
           historical_reference = p_package->>'historical_reference',
           application_note = p_package->>'application_note', notes = p_package->>'notes',
           agreement_id = nullif(p_package->>'agreement_id', '')::uuid
     where id = v_id;
    if not found then return jsonb_build_object('error', 'unknown_package'); end if;
    delete from public.bk_package_labor where package_id = v_id;
    delete from public.bk_package_resources where package_id = v_id;
  end if;
  for v_row in select * from jsonb_array_elements(coalesce(p_labor, '[]'::jsonb)) loop
    if (v_row->>'hours')::numeric > 0 then
      insert into public.bk_package_labor (package_id, labor_class_id, hours)
      values (v_id, (v_row->>'labor_class_id')::uuid, (v_row->>'hours')::numeric);
    end if;
  end loop;
  for v_row in select * from jsonb_array_elements(coalesce(p_resources, '[]'::jsonb)) loop
    if (v_row->>'units')::numeric > 0 then
      insert into public.bk_package_resources (package_id, pool_id, units)
      values (v_id, (v_row->>'pool_id')::uuid, (v_row->>'units')::numeric);
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;


--
-- Name: bk_send_estimate(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_send_estimate(p_project_id uuid, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_project public.bk_projects;
  v_lines integer;
  v_commitments integer;
  v_held integer;
begin
  select * into v_project from public.bk_projects where id = p_project_id for update;
  if v_project.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if v_project.disposition is not null then return jsonb_build_object('error', 'closed'); end if;
  if v_project.stage not in ('request', 'estimate') then return jsonb_build_object('error', 'wrong_stage'); end if;
  select count(*) into v_lines from public.bk_estimate_lines where project_id = p_project_id;
  select count(*) into v_commitments from public.bk_airtime_commitments where project_id = p_project_id;
  if v_lines = 0 and v_commitments = 0 then return jsonb_build_object('error', 'nothing_to_send'); end if;
  if v_lines > 0 and v_project.priced_as is null then return jsonb_build_object('error', 'not_priced'); end if;

  -- Planned dates become holds; an earlier send's holds (live or expired) take the new expiry.
  update public.bk_bookings
     set status = 'tentative', expires_at = p_expires_at,
         treatment = coalesce(v_project.priced_as, treatment)
   where project_id = p_project_id and status in ('planned', 'tentative');
  get diagnostics v_held = row_count;

  update public.bk_projects
     set stage = 'estimate', estimate_sent_at = now(), estimate_expires_at = p_expires_at
   where id = p_project_id;
  return jsonb_build_object('ok', true, 'held', v_held);
end;
$$;


--
-- Name: bk_set_project_disposition(uuid, public.bk_project_disposition, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_set_project_disposition(p_project_id uuid, p_disposition public.bk_project_disposition, p_reason text, p_margin_foregone numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_project public.bk_projects;
  v_released integer;
begin
  if p_reason is null or length(btrim(p_reason)) = 0 then
    return jsonb_build_object('error', 'reason_required');
  end if;
  select * into v_project from public.bk_projects where id = p_project_id for update;
  if v_project.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if v_project.stage in ('delivered', 'settled') then return jsonb_build_object('error', 'wrong_stage'); end if;

  update public.bk_bookings set status = 'released'
   where project_id = p_project_id and status in ('tentative', 'confirmed');
  get diagnostics v_released = row_count;

  -- A reserved block's own date goes too, even while still planned: the block
  -- is the partner's again, and a lingering planned date would double up if
  -- the request were reopened and the block taken a second time.
  update public.bk_bookings b set status = 'released'
    from public.bk_reserved_blocks rb
   where rb.booking_id = b.id and rb.project_id = p_project_id and b.status <> 'released';
  update public.bk_reserved_blocks set project_id = null, booking_id = null
   where project_id = p_project_id;

  update public.bk_projects
     set disposition = p_disposition, disposition_reason = btrim(p_reason),
         disposition_by = auth.uid(), disposition_at = now(),
         estimate_expires_at = null,
         margin_foregone = coalesce(p_margin_foregone, margin_foregone)
   where id = p_project_id;
  return jsonb_build_object('ok', true, 'released', v_released);
end;
$$;


--
-- Name: bk_set_version_in_use(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_set_version_in_use(p_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_status public.bk_version_status;
  v_count integer;
begin
  select status into v_status from public.bk_rate_model_versions where id = p_version_id;
  if v_status is null then return jsonb_build_object('error', 'unknown_version'); end if;
  if v_status = 'superseded' then return jsonb_build_object('error', 'superseded'); end if;
  update public.bk_rate_model_versions set in_use = false where in_use and id <> p_version_id;
  update public.bk_rate_model_versions set in_use = true where id = p_version_id and not in_use;
  get diagnostics v_count = row_count;
  return jsonb_build_object('ok', true, 'changed', v_count > 0);
end;
$$;


--
-- Name: bk_station_today(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_station_today() RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ select (now() at time zone private.station_time_zone())::date; $$;


--
-- Name: bk_submit_request(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_submit_request(p_payload jsonb, p_ip_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_settings public.bk_settings;
  v_email text;
  v_requested public.bk_requested;
  v_partner_kind public.bk_partner_kind;
  v_partner_name text;
  v_partner_id uuid;
  v_packages text[];
  v_package text;
  v_event_starts date;
  v_event_ends date;
  v_due date;
  v_airings integer;
  v_seconds integer;
  v_air_starts date;
  v_air_ends date;
  v_recent integer;
  v_project_id uuid;
begin
  select * into v_settings from public.bk_settings where id = true;
  if v_settings.is_open is not true or not private.tool_is_enabled('bookings') then
    return jsonb_build_object('error', 'closed');
  end if;

  -- Who is asking.
  v_email := lower(trim(p_payload->>'contact_email'));
  if v_email is null or v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then
    return jsonb_build_object('error', 'invalid_email');
  end if;
  v_partner_name := trim(p_payload->>'partner_name');
  if coalesce(trim(p_payload->>'contact_name'), '') = ''
     or coalesce(v_partner_name, '') = ''
     or coalesce(trim(p_payload->>'title'), '') = ''
     or coalesce(trim(p_payload->>'description'), '') = ''
  then
    return jsonb_build_object('error', 'missing_required_field');
  end if;
  if length(trim(p_payload->>'title')) > 160 or length(v_partner_name) > 160 then
    return jsonb_build_object('error', 'too_long');
  end if;
  begin
    v_partner_kind := coalesce(nullif(trim(p_payload->>'partner_kind'), ''), 'uwf_unit')::public.bk_partner_kind;
  exception when invalid_text_representation then
    return jsonb_build_object('error', 'invalid_partner_kind');
  end;

  -- What is asked for.
  begin
    v_requested := (p_payload->>'requested')::public.bk_requested;
  exception when invalid_text_representation then
    return jsonb_build_object('error', 'invalid_requested');
  end;
  if v_requested is null then
    return jsonb_build_object('error', 'invalid_requested');
  end if;

  v_packages := '{}'::text[];
  if v_requested <> 'airtime' and jsonb_typeof(p_payload->'packages') = 'array' then
    for v_package in select trim(value #>> '{}') from jsonb_array_elements(p_payload->'packages') loop
      if v_package is null or v_package = '' then continue; end if;
      if not (v_package = any (v_settings.offered_packages)) then
        return jsonb_build_object('error', 'invalid_package');
      end if;
      if not (v_package = any (v_packages)) then
        v_packages := v_packages || v_package;
      end if;
    end loop;
  end if;

  -- When.
  begin
    v_event_starts := nullif(trim(p_payload->>'event_starts_on'), '')::date;
    v_event_ends := nullif(trim(p_payload->>'event_ends_on'), '')::date;
    v_due := nullif(trim(p_payload->>'deliverables_due_on'), '')::date;
    v_air_starts := nullif(trim(p_payload->>'airtime_starts_on'), '')::date;
    v_air_ends := nullif(trim(p_payload->>'airtime_ends_on'), '')::date;
  exception when invalid_datetime_format or datetime_field_overflow then
    return jsonb_build_object('error', 'invalid_date');
  end;
  if v_event_starts is not null and v_event_ends is not null and v_event_ends < v_event_starts then
    return jsonb_build_object('error', 'invalid_date');
  end if;
  if v_air_starts is not null and v_air_ends is not null and v_air_ends < v_air_starts then
    return jsonb_build_object('error', 'invalid_date');
  end if;

  -- The airtime numbers, when the request asks for airtime.
  if v_requested <> 'production' then
    begin
      v_airings := nullif(trim(p_payload->>'airings_per_week'), '')::integer;
      v_seconds := nullif(trim(p_payload->>'seconds'), '')::integer;
    exception when invalid_text_representation or numeric_value_out_of_range then
      return jsonb_build_object('error', 'invalid_airtime');
    end;
    if (v_airings is not null and (v_airings < 1 or v_airings > 99))
       or (v_seconds is not null and (v_seconds < 1 or v_seconds > 3600)) then
      return jsonb_build_object('error', 'invalid_airtime');
    end if;
  end if;

  -- Bounded per submitter, in the same transaction as the write — the shape
  -- ap_submit_inquiry() uses: an email and a salted address hash are the two
  -- things available with no participant identity.
  select count(*) into v_recent
  from public.bk_projects
  where source = 'public' and lower(contact_email) = v_email
    and created_at > now() - interval '24 hours';
  if v_recent >= 3 then
    return jsonb_build_object('error', 'rate_limited');
  end if;
  if p_ip_hash is not null then
    select count(*) into v_recent
    from public.bk_projects
    where submitted_ip_hash = p_ip_hash and created_at > now() - interval '1 hour';
    if v_recent >= 5 then
      return jsonb_build_object('error', 'rate_limited');
    end if;
  end if;

  -- The partner: the unit or organization on file by name, or a new row. An
  -- existing row is never changed by a public submission — its kind, contact
  -- and index are staff's to keep; the submitter's details go on the project.
  select id into v_partner_id
  from public.bk_partners
  where lower(name) = lower(v_partner_name);
  if v_partner_id is null then
    insert into public.bk_partners (name, kind, contact_name, contact_email, contact_phone)
    values (
      v_partner_name, v_partner_kind,
      trim(p_payload->>'contact_name'), v_email, nullif(trim(p_payload->>'contact_phone'), '')
    )
    returning id into v_partner_id;
  end if;

  insert into public.bk_projects (
    partner_id, title, description, requested, requested_packages,
    event_starts_on, event_ends_on, deliverables_due_on, location,
    contact_name, contact_email, contact_phone,
    source, submitted_ip_hash
  ) values (
    v_partner_id, trim(p_payload->>'title'), trim(p_payload->>'description'), v_requested, v_packages,
    v_event_starts, v_event_ends, v_due, nullif(left(trim(p_payload->>'location'), 200), ''),
    trim(p_payload->>'contact_name'), v_email, nullif(trim(p_payload->>'contact_phone'), ''),
    'public', p_ip_hash
  )
  returning id into v_project_id;

  -- A commitment only when the form gave enough to record one; the rest of
  -- what was said about airtime is in the description for staff to read.
  if v_requested <> 'production' and v_airings is not null and v_seconds is not null
     and coalesce(v_air_starts, v_event_starts) is not null then
    insert into public.bk_airtime_commitments (project_id, airings_per_week, seconds, starts_on, ends_on, notes)
    values (
      v_project_id, v_airings, v_seconds,
      coalesce(v_air_starts, v_event_starts), coalesce(v_air_ends, v_event_ends),
      'Asked for on the public request form.'
    );
  end if;

  insert into public.bk_project_events (project_id, actor_id, kind, note)
  values (v_project_id, null, 'received', 'Submitted through the public request form.');

  return jsonb_build_object('ok', true, 'confirmation_copy', v_settings.confirmation_copy);
end;
$_$;


--
-- Name: bk_university_avails_per_week(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bk_university_avails_per_week(p_plan_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_plan public.bk_term_plans;
  v_as_of date;
  v_programs jsonb;
begin
  if auth.uid() is null or not private.has_bookings_access(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;
  -- The airtime envelope is read from On Air's schedule; with On Air switched off there is nothing
  -- to read, and the Calendar reports it unavailable rather than serving a stale schedule.
  if not private.tool_is_enabled('log') then
    return jsonb_build_object('error', 'on_air_unavailable');
  end if;
  select * into v_plan from public.bk_term_plans where id = p_plan_id;
  if v_plan.id is null then
    return jsonb_build_object('error', 'not_found');
  end if;
  v_as_of := least(greatest(v_plan.starts_on, current_date), v_plan.ends_on);

  with entries as (
    select s.id, s.program_id, s.clock_template_id, s.duration_minutes,
           case when cardinality(s.days_of_week) = 0 then 7 else cardinality(s.days_of_week) end as days,
           case when cardinality(s.days_of_week) = 0 then array[0, 1, 2, 3, 4, 5, 6] else s.days_of_week end as day_set,
           ceil(s.duration_minutes / 60.0)::integer as hours
    from public.log_schedule s
    where s.entry_type = 'recurring'
      and s.start_date <= v_as_of
      and (s.end_date is null or s.end_date >= v_as_of)
  ),
  versions as (
    select distinct on (e.id) e.id as entry_id, v.id as version_id
    from entries e
    join public.log_clock_versions v on v.clock_template_id = e.clock_template_id
    where v.effective_from <= v_as_of and (v.effective_to is null or v.effective_to >= v_as_of)
    order by e.id, v.effective_from desc
  ),
  opportunities as (
    select e.id as entry_id, e.program_id, e.days, e.day_set, e.hours, o.id as opportunity_id, cs.duration_seconds
    from entries e
    join versions v on v.entry_id = e.id
    join public.log_local_opportunities o on o.clock_version_id = v.version_id and o.active
    join public.log_clock_slots cs on cs.id = o.slot_id
    where 'university_announcement' = any (o.permitted_content_types)
  ),
  pins as (
    select op.entry_id, a.id as assignment_id,
           (case when a.hour_index is null then op.hours else 1 end)
             * (case when cardinality(a.days_of_week) = 0 then op.days
                     else (select count(*) from unnest(a.days_of_week) d where d = any (op.day_set)) end) as occurrences,
           coalesce(
             nullif((select sum(c.duration_seconds) from public.log_content_components c where c.content_item_id = ci.id and c.required), 0),
             ci.expected_duration_seconds, 0) as seconds
    from opportunities op
    join public.log_opportunity_assignments a on a.local_opportunity_id = op.opportunity_id and a.active
    join public.log_content_items ci on ci.id = a.content_item_id
  ),
  per_entry as (
    select e.id as entry_id, e.program_id,
           coalesce(count(op.opportunity_id) * max(e.hours) * max(e.days), 0) as avails,
           coalesce(sum(op.duration_seconds) * max(e.hours) * max(e.days), 0) as seconds,
           coalesce((select sum(p.occurrences * p.seconds) from pins p where p.entry_id = e.id), 0) as pinned_seconds
    from entries e
    left join opportunities op on op.entry_id = e.id
    group by e.id, e.program_id
  ),
  per_program as (
    select pe.program_id, pr.name, sum(pe.avails)::integer as avails,
           round(sum(pe.seconds) / 60.0, 1) as minutes, round(sum(pe.pinned_seconds) / 60.0, 1) as pinned_minutes
    from per_entry pe
    join public.log_programs pr on pr.id = pe.program_id
    group by pe.program_id, pr.name
    having sum(pe.avails) > 0
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'program_id', program_id, 'name', name, 'avails_per_week', avails,
    'minutes_per_week', minutes, 'pinned_minutes_per_week', pinned_minutes) order by name), '[]'::jsonb)
  into v_programs from per_program;

  return jsonb_build_object('ok', true, 'as_of', v_as_of, 'programs', v_programs);
end;
$$;


--
-- Name: ei_inquiries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ei_inquiries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    pillar_id uuid,
    pillar_name_snapshot text NOT NULL,
    guiding_question_text text NOT NULL
);


--
-- Name: ei_create_inquiry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ei_create_inquiry(p_pillar_id uuid) RETURNS public.ei_inquiries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pillar public.ep_pillars;
  v_inquiry public.ei_inquiries;
begin
  if not private.has_editorial_inquiry_access(auth.uid()) then
    raise exception 'not authorized';
  end if;

  -- security definer, so this reads past ep_pillars' own RLS the same way
  -- every other cross-tool boundary function in this repo does (e.g.
  -- log_get_program_schedule_context) — the caller only needs
  -- has_editorial_inquiry_access, not a separate editorial-planning grant.
  select * into v_pillar from public.ep_pillars where id = p_pillar_id and active;
  if not found then
    raise exception 'that guiding question is not available';
  end if;
  if v_pillar.guiding_question is null or trim(v_pillar.guiding_question) = '' then
    raise exception 'that pillar has no guiding question yet — set one in Editorial Planning first';
  end if;

  insert into public.ei_inquiries (pillar_id, pillar_name_snapshot, guiding_question_text, created_by)
  values (v_pillar.id, v_pillar.name, v_pillar.guiding_question, auth.uid())
  returning * into v_inquiry;

  insert into public.ei_questions (inquiry_id, parent_id, depth, text, created_by)
  values (v_inquiry.id, null, 0, v_inquiry.guiding_question_text, auth.uid());

  return v_inquiry;
end;
$$;


--
-- Name: handle_auth_user_sign_in(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_auth_user_sign_in() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.profiles
  set
    last_active_at = now(),
    account_status = case when account_status = 'invited' then 'active' else account_status end
  where id = new.id;
  return new;
end;
$$;


--
-- Name: handle_new_auth_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_auth_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.is_anonymous then
    return new;
  end if;

  insert into public.profiles (id, email, display_name, platform_role, account_status, invited_by)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data ->> 'display_name', new.email),
    coalesce((new.raw_user_meta_data ->> 'platform_role')::public.platform_role, 'staff'),
    'invited',
    nullif(new.raw_user_meta_data ->> 'invited_by', '')::uuid
  );
  return new;
end;
$$;


--
-- Name: log_assign_dad_spot_numbers(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_assign_dad_spot_numbers(p_item_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_numbers jsonb;
begin
  if auth.uid() is null then
    return jsonb_build_object('error', 'unauthenticated');
  end if;
  if not private.is_log_traffic(auth.uid()) or not private.has_log_access(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;

  update public.log_rundown_items
     set dad_spot_number = nextval('public.log_dad_spot_seq')
   where id = any (p_item_ids)
     and dad_spot_number is null;

  select coalesce(jsonb_agg(jsonb_build_object('item_id', id, 'spot_number', dad_spot_number)), '[]'::jsonb)
    into v_numbers
    from public.log_rundown_items
   where id = any (p_item_ids);

  return jsonb_build_object('ok', true, 'numbers', v_numbers);
end;
$$;


--
-- Name: log_bump_underwriting_credit(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_bump_underwriting_credit(p_placement_id uuid, p_destination_break_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_placement public.uw_scheduled_placements;
  v_item public.log_rundown_items;
  v_line public.uw_contract_schedule_lines;
  v_source_break public.log_rundown_breaks;
  v_source_rundown public.log_rundowns;
  v_dest_break public.log_rundown_breaks;
  v_dest_rundown public.log_rundowns;
  v_bucket public.uw_demand_buckets;
  v_block text;
  v_result jsonb;
begin
  if auth.uid() is null then
    return jsonb_build_object('error', 'unauthenticated');
  end if;
  if not private.has_underwriting_access(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;

  select * into v_placement from public.uw_scheduled_placements where id = p_placement_id;
  if not found then
    return jsonb_build_object('error', 'unknown_placement');
  end if;
  if v_placement.status = 'superseded' then
    return jsonb_build_object('error', 'already_cleared');
  end if;
  if v_placement.log_rundown_item_id is null then
    return jsonb_build_object('error', 'unknown_item');
  end if;
  select * into v_item from public.log_rundown_items where id = v_placement.log_rundown_item_id;
  if not found then
    return jsonb_build_object('error', 'unknown_item');
  end if;

  select * into v_line from public.uw_contract_schedule_lines where id = v_placement.schedule_line_id;

  -- Movable = a window, preferred or any line's fresh placement. A fixed
  -- position (exact, opening, closing) and a makegood never move.
  if v_line.time_mode in ('exact', 'opening', 'closing') or v_placement.makegood_id is not null then
    return jsonb_build_object('error', 'credit_fixed');
  end if;
  -- Any recorded outcome — aired, missed, moved by the host — pins it.
  if exists (select 1 from public.log_broadcast_events where rundown_item_id = v_item.id) then
    return jsonb_build_object('error', 'already_aired');
  end if;

  select * into v_source_break from public.log_rundown_breaks where id = v_item.break_id;
  select * into v_source_rundown from public.log_rundowns where id = v_source_break.rundown_id;
  v_block := public.uw_automation_block(v_source_break, v_source_rundown);
  if v_block is not null then
    return jsonb_build_object('error', v_block);
  end if;

  select * into v_dest_break from public.log_rundown_breaks where id = p_destination_break_id;
  if not found then
    return jsonb_build_object('error', 'unknown_break');
  end if;
  if v_dest_break.id = v_source_break.id then
    return jsonb_build_object('error', 'same_break');
  end if;
  select * into v_dest_rundown from public.log_rundowns where id = v_dest_break.rundown_id;
  v_block := public.uw_automation_block(v_dest_break, v_dest_rundown);
  if v_block is not null then
    return jsonb_build_object('error', v_block);
  end if;

  -- Never outside its own demand bucket: the move must consume the same
  -- unit of the order it consumes today.
  v_bucket := public.uw_bucket_for_date(v_line, v_dest_rundown.air_date);
  if v_bucket.id is null or v_bucket.id <> v_placement.demand_bucket_id then
    return jsonb_build_object('error', 'different_bucket');
  end if;

  -- Clear, then place, as one subtransaction: the placement runs every
  -- check log_place_underwriting_credit() makes (line, revision, contract,
  -- bucket quota — the cleared unit no longer counts — day cap, one per
  -- contract per break, copy, duration, and the freeze on the destination).
  -- A refusal raises, which rolls the clear back and returns its code.
  begin
    v_result := public.log_clear_underwriting_credit(p_placement_id, true);
    if v_result ? 'error' then
      raise exception using message = 'bump:' || (v_result->>'error');
    end if;
    v_result := public.log_place_underwriting_credit(
      p_destination_break_id, v_line.id, v_placement.copy_id, null, null, true);
    if v_result ? 'error' then
      raise exception using message = 'bump:' || (v_result->>'error');
    end if;
  exception
    when others then
      if sqlerrm like 'bump:%' then
        return jsonb_build_object('error', substr(sqlerrm, 6));
      end if;
      raise;
  end;

  return jsonb_build_object(
    'ok', true,
    'placement_id', v_result->>'placement_id',
    'item_id', v_result->>'item_id',
    'superseded_placement_id', p_placement_id,
    'from_break_id', v_source_break.id,
    'to_break_id', p_destination_break_id
  );
end;
$$;


--
-- Name: log_clear_underwriting_credit(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_clear_underwriting_credit(p_placement_id uuid, p_automated boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_placement public.uw_scheduled_placements;
  v_item public.log_rundown_items;
  v_break public.log_rundown_breaks;
  v_rundown public.log_rundowns;
  v_block text;
  v_retired timestamptz;
begin
  if auth.uid() is null then
    return jsonb_build_object('error', 'unauthenticated');
  end if;
  if not private.has_underwriting_access(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;

  select * into v_placement from public.uw_scheduled_placements where id = p_placement_id;
  if not found then
    return jsonb_build_object('error', 'unknown_placement');
  end if;
  if v_placement.status = 'superseded' then
    return jsonb_build_object('error', 'already_cleared');
  end if;

  if p_automated and v_placement.log_rundown_item_id is not null then
    select * into v_item from public.log_rundown_items where id = v_placement.log_rundown_item_id;
    if found then
      select * into v_break from public.log_rundown_breaks where id = v_item.break_id;
      select * into v_rundown from public.log_rundowns where id = v_break.rundown_id;
      v_block := public.uw_automation_block(v_break, v_rundown);
      if v_block is not null then
        return jsonb_build_object('error', v_block);
      end if;
    end if;
  end if;

  -- An item on a superseded rundown is the record of why a credit was lost
  -- (its missed event and exception hang off it, and deleting it would cascade
  -- them away). Cancelling or revising the order still ends the placement, but
  -- the item stays.
  select lr.superseded_at into v_retired
  from public.log_rundown_items i
  join public.log_rundown_breaks b on b.id = i.break_id
  join public.log_rundowns lr on lr.id = b.rundown_id
  where i.id = v_placement.log_rundown_item_id;
  if v_retired is null then
    delete from public.log_rundown_items where id = v_placement.log_rundown_item_id;
  end if;

  update public.uw_scheduled_placements
  set status = 'superseded'
  where id = p_placement_id;

  if v_placement.makegood_id is not null then
    update public.uw_makegoods
    set scheduled_placement_id = null, scheduled_for = null
    where id = v_placement.makegood_id and status = 'scheduled';
  end if;

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: log_delete_unplaced_credit_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_delete_unplaced_credit_item(p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item public.log_rundown_items;
begin
  if auth.uid() is null or not private.has_log_access(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;

  select * into v_item from public.log_rundown_items where id = p_item_id;
  if not found then
    return jsonb_build_object('error', 'That item no longer exists.');
  end if;
  if v_item.item_kind <> 'underwriting_credit' then
    return jsonb_build_object('error', 'Not an underwriting credit.');
  end if;
  if exists (
    select 1 from public.uw_scheduled_placements
    where log_rundown_item_id = p_item_id
  ) then
    return jsonb_build_object(
      'error',
      'This credit was placed by Underwriting & Traffic — clear it from there instead.'
    );
  end if;

  delete from public.log_rundown_items where id = p_item_id;
  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: log_derive_rundown_break_times(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_derive_rundown_break_times() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rundown public.log_rundowns;
  v_slot public.log_clock_slots;
  v_start integer;
  v_rejoin integer;
begin
  select * into v_rundown from public.log_rundowns where id = new.rundown_id;
  if not found then
    raise exception 'log_rundown_breaks: rundown % does not exist', new.rundown_id;
  end if;

  -- An opportunity identifies its slot on its own.
  if new.clock_slot_id is null and new.local_opportunity_id is not null then
    select slot_id into new.clock_slot_id
    from public.log_local_opportunities where id = new.local_opportunity_id;
  end if;
  if new.clock_slot_id is null then
    raise exception 'log_rundown_breaks: clock_slot_id is required';
  end if;

  select * into v_slot from public.log_clock_slots where id = new.clock_slot_id;
  if not found or v_slot.clock_version_id <> v_rundown.clock_version_id then
    raise exception 'log_rundown_breaks: slot % is not on this rundown''s clock version', new.clock_slot_id;
  end if;

  if new.local_opportunity_id is null then
    select id into new.local_opportunity_id
    from public.log_local_opportunities where slot_id = new.clock_slot_id and active;
  elsif not exists (
    select 1 from public.log_local_opportunities
    where id = new.local_opportunity_id and slot_id = new.clock_slot_id
  ) then
    raise exception 'log_rundown_breaks: opportunity % does not mark slot %', new.local_opportunity_id, new.clock_slot_id;
  end if;

  if v_slot.timing_mode = 'float' then
    v_start := coalesce(v_slot.earliest_start_offset_seconds, v_slot.start_offset_seconds, 0);
    if new.landing_offset_seconds is not null then
      if new.landing_offset_seconds < v_start
         or new.landing_offset_seconds > coalesce(v_slot.latest_start_offset_seconds, v_slot.start_offset_seconds, 0) then
        raise exception 'log_rundown_breaks: landing % is outside slot %''s window', new.landing_offset_seconds, new.clock_slot_id;
      end if;
      v_start := new.landing_offset_seconds;
    end if;
    -- Same rule as generation: the latest permitted start plus the duration.
    v_rejoin := coalesce(v_slot.latest_start_offset_seconds, v_slot.start_offset_seconds, 0) + v_slot.duration_seconds;
  else
    new.landing_offset_seconds := null;
    v_start := coalesce(v_slot.start_offset_seconds, 0);
    v_rejoin := v_start + v_slot.duration_seconds;
  end if;

  if new.hour_index is null then
    new.hour_index := greatest(0, round((extract(epoch from new.scheduled_at - v_rundown.shift_start_at) - v_start) / 3600.0)::integer);
  end if;

  new.scheduled_at := v_rundown.shift_start_at + make_interval(secs => new.hour_index * 3600 + v_start);
  new.available_duration_seconds := v_slot.duration_seconds;
  new.network_rejoin_at := v_rundown.shift_start_at + make_interval(secs => new.hour_index * 3600 + v_rejoin);
  new.label := coalesce(v_slot.label, case when new.local_opportunity_id is null then 'Network slot' else 'Local opportunity' end);
  new.position := new.hour_index * 10000 + v_slot.position;
  return new;
end;
$$;


--
-- Name: log_generate_rundown_for_underwriting(uuid, uuid, uuid, date, timestamp with time zone, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_generate_rundown_for_underwriting(p_program_id uuid, p_schedule_entry_id uuid, p_clock_version_id uuid, p_air_date date, p_shift_start_at timestamp with time zone, p_shift_end_at timestamp with time zone, p_break_drafts jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_existing_id uuid;
  v_rundown_id uuid;
  v_draft jsonb;
begin
  if auth.uid() is null then
    return jsonb_build_object('error', 'unauthenticated');
  end if;
  if not private.has_underwriting_access(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;

  select id into v_existing_id from public.log_rundowns
  where program_id = p_program_id and air_date = p_air_date and superseded_at is null;
  if v_existing_id is not null then
    return jsonb_build_object(
      'ok', true,
      'rundown_id', v_existing_id,
      'already_existed', true,
      'breaks', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'break_id', b.id,
          'clock_slot_id', b.clock_slot_id,
          'hour_index', b.hour_index,
          'local_opportunity_id', b.local_opportunity_id,
          'permitted_content_types', b.permitted_content_types,
          'scheduled_at', b.scheduled_at,
          'available_duration_seconds', b.available_duration_seconds
        )), '[]'::jsonb)
        from public.log_rundown_breaks b
        where b.rundown_id = v_existing_id
      )
    );
  end if;

  -- Automation never provisions the past: a rundown for a date already gone
  -- could only ever be an as-aired record, and that is the host's.
  if p_air_date < public.uw_station_today() then
    return jsonb_build_object('error', 'air_date_in_past');
  end if;

  if not exists (select 1 from public.log_schedule where id = p_schedule_entry_id) then
    return jsonb_build_object('error', 'unknown_schedule_entry');
  end if;
  if not exists (select 1 from public.log_clock_versions where id = p_clock_version_id) then
    return jsonb_build_object('error', 'unknown_clock_version');
  end if;

  insert into public.log_rundowns (
    program_id, schedule_entry_id, clock_version_id, air_date, shift_start_at, shift_end_at, status, generated_at
  ) values (
    p_program_id, p_schedule_entry_id, p_clock_version_id, p_air_date, p_shift_start_at, p_shift_end_at, 'generated', now()
  )
  returning id into v_rundown_id;

  for v_draft in select * from jsonb_array_elements(p_break_drafts)
  loop
    -- scheduled_at, available_duration_seconds, network_rejoin_at, label and
    -- position are derived from the slot by log_derive_rundown_break_times();
    -- the draft's values are passed only because the columns are not null.
    insert into public.log_rundown_breaks (
      rundown_id, clock_slot_id, hour_index, local_opportunity_id, position, label, requirement,
      permitted_content_types, scheduled_at, available_duration_seconds, network_rejoin_at
    ) values (
      v_rundown_id,
      (v_draft->>'clock_slot_id')::uuid,
      (v_draft->>'hour_index')::integer,
      (v_draft->>'local_opportunity_id')::uuid,
      (v_draft->>'position')::integer,
      v_draft->>'label',
      (v_draft->>'requirement')::public.log_opportunity_requirement,
      (select coalesce(array_agg(x), '{}'::text[]) from jsonb_array_elements_text(v_draft->'permitted_content_types') as x),
      (v_draft->>'scheduled_at')::timestamptz,
      (v_draft->>'available_duration_seconds')::integer,
      (v_draft->>'network_rejoin_at')::timestamptz
    )
    on conflict (rundown_id, clock_slot_id, hour_index) do nothing;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'rundown_id', v_rundown_id,
    'already_existed', false,
    'breaks', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'break_id', b.id,
        'clock_slot_id', b.clock_slot_id,
        'hour_index', b.hour_index,
        'local_opportunity_id', b.local_opportunity_id,
        'permitted_content_types', b.permitted_content_types,
        'scheduled_at', b.scheduled_at,
        'available_duration_seconds', b.available_duration_seconds
      )), '[]'::jsonb)
      from public.log_rundown_breaks b
      where b.rundown_id = v_rundown_id
    )
  );
end;
$$;


--
-- Name: log_get_program_schedule_context(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_get_program_schedule_context(p_program_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_schedule_entries jsonb;
  v_clock_versions jsonb;
  v_local_opportunities jsonb;
  v_opportunity_assignments jsonb;
  v_content_items jsonb;
  v_existing_rundown_dates jsonb;
begin
  if auth.uid() is null or not private.has_underwriting_access(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', s.id,
    'clock_template_id', s.clock_template_id,
    'entry_type', s.entry_type,
    'days_of_week', s.days_of_week,
    'start_date', s.start_date,
    'end_date', s.end_date,
    'air_time', s.air_time,
    'duration_minutes', s.duration_minutes
  )), '[]'::jsonb)
  into v_schedule_entries
  from public.log_schedule s
  where s.program_id = p_program_id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', v.id,
    'clock_template_id', v.clock_template_id,
    'variant', v.variant,
    'effective_from', v.effective_from,
    'effective_to', v.effective_to
  )), '[]'::jsonb)
  into v_clock_versions
  from public.log_clock_versions v
  where v.clock_template_id in (select clock_template_id from public.log_schedule where program_id = p_program_id);

  -- Slot-keyed (restored from 20260809170000 — see this migration's own
  -- header): every opportunity's offset/duration/label/timing come from a
  -- join to its referenced network slot, since those columns don't exist on
  -- log_local_opportunities itself.
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', o.id,
    'clock_version_id', o.clock_version_id,
    'slot_id', cs.id,
    'slot_position', cs.position,
    'slot_label', cs.label,
    'requirement', o.requirement,
    'timing_mode', cs.timing_mode,
    'start_offset_seconds', cs.start_offset_seconds,
    'duration_seconds', cs.duration_seconds,
    'earliest_start_offset_seconds', cs.earliest_start_offset_seconds,
    'latest_start_offset_seconds', cs.latest_start_offset_seconds,
    'permitted_content_types', o.permitted_content_types
  )), '[]'::jsonb)
  into v_local_opportunities
  from public.log_local_opportunities o
  join public.log_clock_slots cs on cs.id = o.slot_id
  where o.active
    and o.clock_version_id in (
      select v.id from public.log_clock_versions v
      where v.clock_template_id in (select clock_template_id from public.log_schedule where program_id = p_program_id)
    );

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', a.id,
    'local_opportunity_id', a.local_opportunity_id,
    'content_item_id', a.content_item_id,
    'hour_index', a.hour_index,
    'days_of_week', a.days_of_week,
    'active', a.active
  )), '[]'::jsonb)
  into v_opportunity_assignments
  from public.log_opportunity_assignments a
  where a.active
    and a.local_opportunity_id in (
      select o.id from public.log_local_opportunities o
      where o.active
        and o.clock_version_id in (
          select v.id from public.log_clock_versions v
          where v.clock_template_id in (select clock_template_id from public.log_schedule where program_id = p_program_id)
        )
    );

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', ci.id,
    'expected_duration_seconds', ci.expected_duration_seconds,
    'components', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'component_type', c.component_type,
        'duration_seconds', c.duration_seconds,
        'required', c.required
      )), '[]'::jsonb)
      from public.log_content_components c
      where c.content_item_id = ci.id
    )
  )), '[]'::jsonb)
  into v_content_items
  from public.log_content_items ci
  where ci.id in (
    select a.content_item_id from public.log_opportunity_assignments a
    where a.active
      and a.local_opportunity_id in (
        select o.id from public.log_local_opportunities o
        where o.active
          and o.clock_version_id in (
            select v.id from public.log_clock_versions v
            where v.clock_template_id in (select clock_template_id from public.log_schedule where program_id = p_program_id)
          )
      )
  );

  select coalesce(jsonb_agg(r.air_date), '[]'::jsonb)
  into v_existing_rundown_dates
  from public.log_rundowns r
  where r.program_id = p_program_id and r.superseded_at is null;

  return jsonb_build_object(
    'ok', true,
    'schedule_entries', v_schedule_entries,
    'clock_versions', v_clock_versions,
    'local_opportunities', v_local_opportunities,
    'opportunity_assignments', v_opportunity_assignments,
    'content_items', v_content_items,
    'existing_rundown_dates', v_existing_rundown_dates
  );
end;
$$;


--
-- Name: log_import_list_underwriting_copy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_import_list_underwriting_copy() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null or not private.has_log_access(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;

  return jsonb_build_object(
    'underwriters',
    coalesce(
      (
        select jsonb_agg(jsonb_build_object('id', u.id, 'name', u.name) order by u.name)
        from public.uw_underwriters u
      ),
      '[]'::jsonb
    ),
    'copy',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', c.id,
            'underwriter_id', c.underwriter_id,
            'label', c.label,
            'cart_identifier', c.cart_identifier,
            'script', c.script,
            'duration_seconds', c.duration_seconds,
            'approval_status', c.approval_status
          )
          order by c.created_at
        )
        from public.uw_copy c
      ),
      '[]'::jsonb
    )
  );
end;
$$;


--
-- Name: log_import_underwriter(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_import_underwriter(p_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_name text;
begin
  if auth.uid() is null or not private.has_log_access(auth.uid()) then
    raise exception 'forbidden';
  end if;

  v_name := btrim(coalesce(p_name, ''));
  if v_name = '' then
    raise exception 'underwriter name is required';
  end if;

  select id into v_id
  from public.uw_underwriters
  where lower(name) = lower(v_name)
  order by created_at
  limit 1;
  if found then
    return v_id;
  end if;

  insert into public.uw_underwriters (name, created_by)
  values (v_name, auth.uid())
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: log_import_underwriting_copy(uuid, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_import_underwriting_copy(p_underwriter_id uuid, p_label text, p_cart_identifier text, p_script text, p_duration_seconds integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_label text;
  v_cart text;
  v_script text;
  v_duration integer;
  v_updated integer;
begin
  if auth.uid() is null or not private.has_log_access(auth.uid()) then
    raise exception 'forbidden';
  end if;

  v_label := btrim(coalesce(p_label, ''));
  v_cart := nullif(btrim(coalesce(p_cart_identifier, '')), '');
  v_script := nullif(btrim(coalesce(p_script, '')), '');
  v_duration := case when p_duration_seconds > 0 then p_duration_seconds end;
  if v_label = '' then
    raise exception 'copy label is required';
  end if;
  if not exists (select 1 from public.uw_underwriters where id = p_underwriter_id) then
    raise exception 'unknown underwriter';
  end if;

  select id into v_id
  from public.uw_copy
  where underwriter_id = p_underwriter_id
    and label = v_label
    and cart_identifier is not distinct from v_cart
  order by created_at
  limit 1;
  if found then
    update public.uw_copy
    set duration_seconds = case
          when v_script is not null and script is distinct from v_script
            then coalesce(v_duration, duration_seconds)
          else coalesce(duration_seconds, v_duration)
        end,
        script = coalesce(v_script, script)
    where id = v_id
      and (
        (v_script is not null and script is distinct from v_script)
        or (duration_seconds is null and v_duration is not null)
      );
    get diagnostics v_updated = row_count;
    if v_updated > 0 then
      perform private.uw_reconcile_imported_copy(v_id);
    end if;
    return v_id;
  end if;

  insert into public.uw_copy (
    underwriter_id, label, cart_identifier, script, duration_seconds,
    execution_kind, approval_status, created_by
  ) values (
    p_underwriter_id, v_label, v_cart, v_script, v_duration,
    case when private.uw_script_plays_recording(v_script)
         then 'recorded'::public.uw_copy_execution_kind
         else 'live_read'::public.uw_copy_execution_kind end,
    'approved', auth.uid()
  )
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: log_import_update_underwriting_copy(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_import_update_underwriting_copy(p_copy_id uuid, p_script text, p_duration_seconds integer DEFAULT NULL::integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_script text;
  v_updated integer;
begin
  if auth.uid() is null or not private.has_log_access(auth.uid()) then
    raise exception 'forbidden';
  end if;

  v_script := nullif(btrim(coalesce(p_script, '')), '');
  if v_script is null then
    return false;
  end if;

  update public.uw_copy
  set script = v_script,
      duration_seconds = coalesce(
        case when p_duration_seconds > 0 then p_duration_seconds end,
        duration_seconds
      )
  where id = p_copy_id
    and script is distinct from v_script;
  get diagnostics v_updated = row_count;
  if v_updated > 0 then
    perform private.uw_reconcile_imported_copy(p_copy_id);
  end if;
  return v_updated > 0;
end;
$$;


--
-- Name: log_insert_rundown_items_for_underwriting(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_insert_rundown_items_for_underwriting(p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item jsonb;
  v_inserted integer := 0;
begin
  if auth.uid() is null then
    return jsonb_build_object('error', 'unauthenticated');
  end if;
  if not private.has_underwriting_access(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    insert into public.log_rundown_items (
      break_id, position, item_kind, content_item_id, planned_duration_seconds, placement_status
    )
    select
      (v_item->>'break_id')::uuid,
      (v_item->>'position')::integer,
      'content',
      (v_item->>'content_item_id')::uuid,
      (v_item->>'planned_duration_seconds')::integer,
      'replaceable'
    where exists (select 1 from public.log_rundown_breaks where id = (v_item->>'break_id')::uuid);
    if found then
      v_inserted := v_inserted + 1;
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'inserted', v_inserted);
end;
$$;


--
-- Name: log_list_placeable_rundown_breaks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_list_placeable_rundown_breaks(p_schedule_line_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_line public.uw_contract_schedule_lines;
  v_contract public.uw_contracts;
  v_breaks jsonb;
begin
  if auth.uid() is null or not private.has_underwriting_access(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;

  select * into v_line from public.uw_contract_schedule_lines where id = p_schedule_line_id;
  if not found then
    return jsonb_build_object('error', 'unknown_schedule_line');
  end if;
  select * into v_contract from public.uw_contracts where id = v_line.contract_id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'break_id', b.id,
    'rundown_id', lr.id,
    'rundown_status', lr.status,
    'air_date', lr.air_date,
    'scheduled_at', b.scheduled_at,
    'minutes_of_day', (extract(hour from public.uw_station_local_time(b.scheduled_at)) * 60
                       + extract(minute from public.uw_station_local_time(b.scheduled_at)))::integer,
    'label', b.label,
    'program_name', lp.name,
    'bucket_id', bucket.id,
    'remaining_seconds', b.available_duration_seconds - coalesce(occupied.total, 0),
    'last_item_id', last_item.id,
    'holds_this_contract', exists (
      select 1 from public.uw_scheduled_placements sp
      join public.log_rundown_items ci on ci.id = sp.log_rundown_item_id
      join public.uw_contract_schedule_lines sl on sl.id = sp.schedule_line_id
      where ci.break_id = b.id and sp.status <> 'superseded' and sl.contract_id = v_contract.id
    ),
    'items', coalesce(items.list, '[]'::jsonb)
  ) order by b.scheduled_at), '[]'::jsonb)
  into v_breaks
  from public.log_rundown_breaks b
  join public.log_rundowns lr on lr.id = b.rundown_id
  join public.log_programs lp on lp.id = lr.program_id
  cross join lateral (select * from public.uw_bucket_for_date(v_line, lr.air_date)) bucket
  left join lateral (
    select sum(i.planned_duration_seconds) as total
    from public.log_rundown_items i
    where i.break_id = b.id
  ) occupied on true
  left join lateral (
    select i.id
    from public.log_rundown_items i
    where i.break_id = b.id
    order by i.position desc
    limit 1
  ) last_item on true
  left join lateral (
    -- Every item in the break, credits carrying the placement, line and
    -- underwriter behind them (null for host content) — the bump planner's
    -- view of who could make room.
    select jsonb_agg(jsonb_build_object(
      'item_id', i.id,
      'position', i.position,
      'duration_seconds', coalesce(i.planned_duration_seconds, 0),
      'placement_id', sp.id,
      'schedule_line_id', sp.schedule_line_id,
      'contract_id', sl.contract_id,
      'underwriter_id', c.underwriter_id,
      'category_id', u.category_id,
      'time_mode', sl.time_mode,
      'service_level', sl.service_level,
      'makegood_id', sp.makegood_id,
      'bucket_id', sp.demand_bucket_id,
      'has_outcome', exists (
        select 1 from public.log_broadcast_events e where e.rundown_item_id = i.id
      )
    ) order by i.position) as list
    from public.log_rundown_items i
    left join public.uw_scheduled_placements sp
      on sp.log_rundown_item_id = i.id and sp.status <> 'superseded'
    left join public.uw_contract_schedule_lines sl on sl.id = sp.schedule_line_id
    left join public.uw_contracts c on c.id = sl.contract_id
    left join public.uw_underwriters u on u.id = c.underwriter_id
    where i.break_id = b.id
  ) items on true
  where 'underwriting_credit' = any(b.permitted_content_types)
    and lr.superseded_at is null
    and b.local_opportunity_id is not null
    and bucket.id is not null
    and (v_line.program_id is null or lr.program_id = v_line.program_id)
    and (v_line.pool_id is null or public.uw_pool_matches(
      v_line.pool_id, lr.program_id, public.uw_station_local_time(b.scheduled_at), extract(dow from lr.air_date)::integer))
    and public.uw_time_eligible(v_line, public.uw_station_local_time(b.scheduled_at))
    and public.uw_break_position_eligible(v_line, b);

  return jsonb_build_object('ok', true, 'breaks', v_breaks);
end;
$$;


--
-- Name: log_list_programs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_list_programs() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when auth.uid() is null or not (
      private.has_underwriting_access(auth.uid()) or private.has_log_access(auth.uid())
    ) then jsonb_build_object('error', 'forbidden')
    else jsonb_build_object('ok', true, 'programs', coalesce((
      select jsonb_agg(jsonb_build_object('id', id, 'name', name) order by name)
      from public.log_programs
    ), '[]'::jsonb))
  end;
$$;


--
-- Name: log_list_underwriting_credit_rooms(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_list_underwriting_credit_rooms(p_contract_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rooms jsonb;
begin
  if auth.uid() is null or not private.has_underwriting_access(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'placement_id', sp.id,
    -- The break's remaining room plus this item's own current length: what
    -- the slot could hold if its message were swapped.
    'room_seconds', b.available_duration_seconds - coalesce(occupied.total, 0)
                    + coalesce(i.planned_duration_seconds, 0),
    'rundown_status', lr.status,
    'break_scheduled_at', b.scheduled_at,
    'has_outcome', exists (
      select 1 from public.log_broadcast_events e where e.rundown_item_id = i.id
    )
  ) order by sp.scheduled_at), '[]'::jsonb)
  into v_rooms
  from public.uw_scheduled_placements sp
  join public.uw_contract_schedule_lines sl on sl.id = sp.schedule_line_id
  join public.log_rundown_items i on i.id = sp.log_rundown_item_id
  join public.log_rundown_breaks b on b.id = i.break_id
  join public.log_rundowns lr on lr.id = b.rundown_id
  left join lateral (
    select sum(x.planned_duration_seconds) as total
    from public.log_rundown_items x
    where x.break_id = b.id
  ) occupied on true
  where sl.contract_id = p_contract_id
    and sp.status <> 'superseded';

  return jsonb_build_object('ok', true, 'rooms', v_rooms);
end;
$$;


--
-- Name: log_place_underwriting_credit(uuid, uuid, uuid, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_place_underwriting_credit(p_break_id uuid, p_schedule_line_id uuid, p_copy_id uuid, p_override_reason text DEFAULT NULL::text, p_makegood_id uuid DEFAULT NULL::uuid, p_automated boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_break public.log_rundown_breaks;
  v_rundown public.log_rundowns;
  v_program public.log_programs;
  v_line public.uw_contract_schedule_lines;
  v_revision public.uw_contract_revisions;
  v_contract public.uw_contracts;
  v_copy public.uw_copy;
  v_link public.uw_contract_copy;
  v_makegood public.uw_makegoods;
  v_exception public.uw_exceptions;
  v_bucket public.uw_demand_buckets;
  v_local_time time;
  v_dow integer;
  v_needs_override boolean;
  v_occupied integer;
  v_in_bucket integer;
  v_on_day integer;
  v_next_position integer;
  v_item_id uuid;
  v_placement_id uuid;
  v_block text;
begin
  if auth.uid() is null then
    return jsonb_build_object('error', 'unauthenticated');
  end if;
  if not private.has_underwriting_access(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;

  -- Serialize every placement against one schedule line: two staff actions
  -- (or auto-fill and a manual pick) racing for the same bucket wait here,
  -- and the second one sees the first's row in the counts below.
  select * into v_line from public.uw_contract_schedule_lines where id = p_schedule_line_id for update;
  if not found then
    return jsonb_build_object('error', 'unknown_schedule_line');
  end if;
  if v_line.status <> 'active' then
    return jsonb_build_object('error', 'line_cancelled');
  end if;

  select * into v_revision from public.uw_contract_revisions where id = v_line.revision_id;
  if v_revision.status <> 'current' then
    return jsonb_build_object('error', 'revision_not_current');
  end if;

  select * into v_contract from public.uw_contracts where id = v_line.contract_id;
  if v_contract.status <> 'active' then
    return jsonb_build_object('error', 'contract_not_active');
  end if;

  select * into v_break from public.log_rundown_breaks where id = p_break_id;
  if not found then
    return jsonb_build_object('error', 'unknown_break');
  end if;
  if not ('underwriting_credit' = any(v_break.permitted_content_types)) or v_break.local_opportunity_id is null then
    return jsonb_build_object('error', 'break_not_eligible');
  end if;

  select * into v_rundown from public.log_rundowns where id = v_break.rundown_id;
  select * into v_program from public.log_programs where id = v_rundown.program_id;

  -- Automation never writes into a live or submitted rundown, or a break
  -- that has already started. A staffer's own manual placement may.
  if p_automated then
    v_block := public.uw_automation_block(v_break, v_rundown);
    if v_block is not null then
      return jsonb_build_object('error', v_block);
    end if;
  end if;

  -- Hours closed to underwriting (20261005130000): automation never adds a
  -- credit there. Checked here, not in uw_automation_block(), because that
  -- helper also gates log_clear_underwriting_credit() and automation must
  -- still be able to clear a credit a staffer placed by hand into closed
  -- hours. Bumping's destination is covered too: it places through here.
  if p_automated and private.log_is_closed_to_underwriting(v_break.scheduled_at) then
    return jsonb_build_object('error', 'hours_closed');
  end if;

  v_local_time := public.uw_station_local_time(v_break.scheduled_at);
  v_dow := extract(dow from v_rundown.air_date)::integer;

  v_bucket := public.uw_bucket_for_date(v_line, v_rundown.air_date);
  if v_bucket.id is null then
    return jsonb_build_object('error', 'date_not_eligible');
  end if;
  if v_line.program_id is not null and v_line.program_id <> v_rundown.program_id then
    return jsonb_build_object('error', 'program_not_eligible');
  end if;
  if v_line.pool_id is not null and not public.uw_pool_matches(v_line.pool_id, v_rundown.program_id, v_local_time, v_dow) then
    return jsonb_build_object('error', 'pool_not_eligible');
  end if;
  if not public.uw_time_eligible(v_line, v_local_time) then
    return jsonb_build_object('error', case v_line.time_mode
      when 'window' then 'outside_window'
      when 'exact' then 'exact_time_mismatch'
      else 'time_not_eligible' end);
  end if;
  if not public.uw_break_position_eligible(v_line, v_break) then
    return jsonb_build_object('error', case v_line.time_mode
      when 'opening' then 'not_opening_break'
      else 'not_closing_break' end);
  end if;

  -- One credit per contract per break — the same underwriter never runs
  -- back to back, and never twice in one avail.
  if exists (
    select 1 from public.uw_scheduled_placements sp
    join public.log_rundown_items ci on ci.id = sp.log_rundown_item_id
    join public.uw_contract_schedule_lines sl on sl.id = sp.schedule_line_id
    where ci.break_id = p_break_id and sp.status <> 'superseded' and sl.contract_id = v_contract.id
  ) then
    return jsonb_build_object('error', 'same_contract_in_break');
  end if;

  if p_makegood_id is null then
    select count(*) into v_in_bucket from public.uw_scheduled_placements
    where demand_bucket_id = v_bucket.id and status <> 'superseded' and makegood_id is null;
    if v_in_bucket >= v_bucket.quantity_required then
      return jsonb_build_object('error', 'bucket_quota_met');
    end if;
  else
    select * into v_makegood from public.uw_makegoods where id = p_makegood_id;
    if not found or v_makegood.schedule_line_id <> v_line.id then
      return jsonb_build_object('error', 'unknown_makegood');
    end if;
    if v_makegood.status <> 'scheduled' or v_makegood.scheduled_placement_id is not null then
      return jsonb_build_object('error', 'makegood_already_scheduled');
    end if;
    select * into v_exception from public.uw_exceptions where id = v_makegood.exception_id;
    if v_exception.makegood_approval in ('pending', 'declined') then
      return jsonb_build_object('error', 'makegood_needs_approval');
    end if;
    -- The replacement is attributed to the bucket the order missed.
    if v_makegood.demand_bucket_id is not null then
      select * into v_bucket from public.uw_demand_buckets where id = v_makegood.demand_bucket_id;
    end if;
  end if;

  if v_line.max_per_day is not null then
    select count(*) into v_on_day from public.uw_scheduled_placements
    where schedule_line_id = v_line.id and status <> 'superseded' and placement_date = v_rundown.air_date;
    if v_on_day >= v_line.max_per_day then
      return jsonb_build_object('error', 'day_cap_met');
    end if;
  end if;

  select * into v_copy from public.uw_copy where id = p_copy_id;
  if not found then
    return jsonb_build_object('error', 'unknown_copy');
  end if;
  select * into v_link from public.uw_contract_copy
  where contract_id = v_line.contract_id and copy_id = p_copy_id;
  if not found then
    return jsonb_build_object('error', 'copy_not_linked');
  end if;
  if v_link.flight_id is not null and v_link.flight_id is distinct from v_line.flight_id then
    return jsonb_build_object('error', 'copy_wrong_flight');
  end if;

  if v_copy.duration_seconds is null then
    return jsonb_build_object('error', 'copy_duration_unknown');
  end if;
  select coalesce(sum(planned_duration_seconds), 0) into v_occupied
    from public.log_rundown_items where break_id = p_break_id;
  if v_copy.duration_seconds > (v_break.available_duration_seconds - v_occupied) then
    return jsonb_build_object('error', 'too_long');
  end if;

  v_needs_override := v_copy.approval_status <> 'approved'
    or v_copy.effective_from > v_rundown.air_date
    or (v_copy.effective_to is not null and v_copy.effective_to < v_rundown.air_date);
  if v_needs_override then
    if p_override_reason is null or trim(p_override_reason) = '' then
      return jsonb_build_object('error', 'copy_needs_override');
    end if;
    if not private.is_underwriting_manager(auth.uid()) then
      return jsonb_build_object('error', 'override_requires_manager');
    end if;
  end if;

  select coalesce(max(position), 0) + 1 into v_next_position
    from public.log_rundown_items where break_id = p_break_id;

  insert into public.log_rundown_items (
    break_id, position, item_kind, underwriting_copy_id, planned_duration_seconds, placement_status
  ) values (
    p_break_id, v_next_position, 'underwriting_credit', p_copy_id, v_copy.duration_seconds, 'replaceable'
  )
  returning id into v_item_id;

  insert into public.uw_scheduled_placements (
    schedule_line_id, copy_id, log_rundown_item_id, placement_date, scheduled_at,
    program_id, program_name, break_label, status, override_reason, created_by,
    demand_bucket_id, makegood_id
  ) values (
    p_schedule_line_id, p_copy_id, v_item_id, v_rundown.air_date, v_break.scheduled_at,
    v_rundown.program_id, v_program.name, v_break.label,
    'scheduled', case when v_needs_override then p_override_reason else null end, auth.uid(),
    v_bucket.id, p_makegood_id
  )
  returning id into v_placement_id;

  if p_makegood_id is not null then
    update public.uw_makegoods
    set scheduled_placement_id = v_placement_id, scheduled_for = v_break.scheduled_at
    where id = p_makegood_id;
  end if;

  return jsonb_build_object('ok', true, 'placement_id', v_placement_id, 'item_id', v_item_id,
    'bucket_id', v_bucket.id, 'period_start', v_bucket.period_start, 'period_end', v_bucket.period_end);
end;
$$;


--
-- Name: log_reassign_underwriting_credit_copy(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_reassign_underwriting_credit_copy(p_placement_id uuid, p_copy_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_placement public.uw_scheduled_placements;
  v_line public.uw_contract_schedule_lines;
  v_contract public.uw_contracts;
  v_item public.log_rundown_items;
  v_break public.log_rundown_breaks;
  v_rundown public.log_rundowns;
  v_copy public.uw_copy;
  v_link public.uw_contract_copy;
  v_block text;
  v_occupied integer;
begin
  if auth.uid() is null then
    return jsonb_build_object('error', 'unauthenticated');
  end if;
  if not private.has_underwriting_access(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;

  select * into v_placement from public.uw_scheduled_placements where id = p_placement_id;
  if not found then
    return jsonb_build_object('error', 'unknown_placement');
  end if;
  if v_placement.status = 'superseded' then
    return jsonb_build_object('error', 'already_cleared');
  end if;
  if v_placement.override_reason is not null then
    return jsonb_build_object('error', 'placement_pinned');
  end if;
  if v_placement.copy_id = p_copy_id then
    return jsonb_build_object('ok', true, 'changed', false);
  end if;

  -- Same lock the placement guard takes, so two walks over one contract
  -- serialize per line rather than interleave.
  select * into v_line from public.uw_contract_schedule_lines
    where id = v_placement.schedule_line_id for update;
  if not found then
    return jsonb_build_object('error', 'unknown_schedule_line');
  end if;
  select * into v_contract from public.uw_contracts where id = v_line.contract_id;
  if v_contract.status <> 'active' then
    return jsonb_build_object('error', 'contract_not_active');
  end if;

  if v_placement.log_rundown_item_id is null then
    return jsonb_build_object('error', 'unknown_item');
  end if;
  select * into v_item from public.log_rundown_items where id = v_placement.log_rundown_item_id;
  if not found then
    return jsonb_build_object('error', 'unknown_item');
  end if;
  if exists (select 1 from public.log_broadcast_events e where e.rundown_item_id = v_item.id) then
    return jsonb_build_object('error', 'already_aired');
  end if;
  select * into v_break from public.log_rundown_breaks where id = v_item.break_id;
  select * into v_rundown from public.log_rundowns where id = v_break.rundown_id;
  v_block := public.uw_automation_block(v_break, v_rundown);
  if v_block is not null then
    return jsonb_build_object('error', v_block);
  end if;

  select * into v_copy from public.uw_copy where id = p_copy_id;
  if not found then
    return jsonb_build_object('error', 'unknown_copy');
  end if;
  select * into v_link from public.uw_contract_copy
    where contract_id = v_line.contract_id and copy_id = p_copy_id;
  if not found then
    return jsonb_build_object('error', 'copy_not_linked');
  end if;
  if v_link.flight_id is not null and v_link.flight_id is distinct from v_line.flight_id then
    return jsonb_build_object('error', 'copy_wrong_flight');
  end if;
  if v_copy.approval_status <> 'approved'
    or v_copy.effective_from > v_rundown.air_date
    or (v_copy.effective_to is not null and v_copy.effective_to < v_rundown.air_date) then
    return jsonb_build_object('error', 'copy_not_approved');
  end if;
  if v_copy.duration_seconds is null then
    return jsonb_build_object('error', 'copy_duration_unknown');
  end if;
  select coalesce(sum(planned_duration_seconds), 0) into v_occupied
    from public.log_rundown_items where break_id = v_break.id and id <> v_item.id;
  if v_copy.duration_seconds > (v_break.available_duration_seconds - v_occupied) then
    return jsonb_build_object('error', 'too_long');
  end if;

  update public.log_rundown_items
  set underwriting_copy_id = p_copy_id, planned_duration_seconds = v_copy.duration_seconds
  where id = v_item.id;

  update public.uw_scheduled_placements
  set copy_id = p_copy_id
  where id = p_placement_id;

  return jsonb_build_object('ok', true, 'changed', true);
end;
$$;


--
-- Name: log_refuse_items_on_superseded_rundown(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_refuse_items_on_superseded_rundown() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if exists (
    select 1
    from public.log_rundown_breaks b
    join public.log_rundowns lr on lr.id = b.rundown_id
    where b.id = new.break_id and lr.superseded_at is not null
  ) then
    raise exception 'rundown_superseded: this rundown was replaced by one on another clock'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


--
-- Name: log_relocate_underwriting_credit(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_relocate_underwriting_credit(p_item_id uuid, p_destination_break_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item public.log_rundown_items;
  v_source_break public.log_rundown_breaks;
  v_placement public.uw_scheduled_placements;
  v_dest_break public.log_rundown_breaks;
  v_dest_rundown public.log_rundowns;
  v_program public.log_programs;
  v_occupied integer;
  v_next_position integer;
  v_open_exception_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('error', 'unauthenticated');
  end if;
  if not private.has_log_access(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;

  select * into v_item from public.log_rundown_items where id = p_item_id;
  if not found or v_item.item_kind <> 'underwriting_credit' then
    return jsonb_build_object('error', 'not_a_credit');
  end if;

  if exists (
    select 1 from public.log_broadcast_events
    where rundown_item_id = p_item_id and outcome = 'aired_as_scheduled'
  ) then
    return jsonb_build_object('error', 'already_aired');
  end if;

  select * into v_source_break from public.log_rundown_breaks where id = v_item.break_id;

  -- A program-log-imported credit legitimately has no uw_scheduled_placements
  -- row at all (see this migration's header) — that's a normal state, not an
  -- error, so v_placement is simply left null (found stays false) rather
  -- than short-circuiting the whole function the way it used to.
  select * into v_placement from public.uw_scheduled_placements
    where log_rundown_item_id = p_item_id and status <> 'superseded'
    order by created_at desc limit 1;

  select * into v_dest_break from public.log_rundown_breaks where id = p_destination_break_id;
  if not found then
    return jsonb_build_object('error', 'unknown_break');
  end if;
  if v_dest_break.id = v_source_break.id then
    return jsonb_build_object('error', 'same_break');
  end if;
  if v_dest_break.rundown_id <> v_source_break.rundown_id then
    return jsonb_build_object('error', 'different_rundown');
  end if;
  if not ('underwriting_credit' = any(v_dest_break.permitted_content_types)) then
    return jsonb_build_object('error', 'break_not_eligible');
  end if;

  -- Excludes the item itself: it's still sitting in the source break at
  -- this point (nothing has moved yet), so it must not count against its
  -- own destination's duration math.
  select coalesce(sum(planned_duration_seconds), 0)
    into v_occupied
    from public.log_rundown_items where break_id = p_destination_break_id and id <> p_item_id;
  if v_item.planned_duration_seconds > (v_dest_break.available_duration_seconds - v_occupied) then
    return jsonb_build_object('error', 'too_long');
  end if;

  select * into v_dest_rundown from public.log_rundowns where id = v_dest_break.rundown_id;
  select * into v_program from public.log_programs where id = v_dest_rundown.program_id;

  select coalesce(max(position), 0) + 1 into v_next_position
    from public.log_rundown_items where break_id = p_destination_break_id and id <> p_item_id;

  update public.log_rundown_items
  set break_id = p_destination_break_id,
      position = v_next_position
  where id = p_item_id;

  if v_placement.id is not null then
    update public.uw_scheduled_placements
    set scheduled_at = v_dest_break.scheduled_at,
        break_label = v_dest_break.label,
        program_id = v_dest_rundown.program_id,
        program_name = v_program.name
    where id = v_placement.id;
  end if;

  select ex.id into v_open_exception_id
  from public.log_broadcast_events lbe
  join public.uw_exceptions ex on ex.log_broadcast_event_id = lbe.id
  where lbe.rundown_item_id = p_item_id
    and ex.resolution_status = 'open'
  order by lbe.recorded_at desc
  limit 1;

  if v_open_exception_id is not null then
    update public.uw_exceptions
    set resolution_status = 'resolved',
        resolution_action = 'reassign',
        resolution_notes = coalesce(resolution_notes || E'\n\n', '')
          || 'Automatically resolved: the host moved this credit to another break in the same broadcast.',
        resolved_by = auth.uid(),
        resolved_at = now()
    where id = v_open_exception_id;
  end if;

  return jsonb_build_object('ok', true, 'item_id', p_item_id, 'placement_id', v_placement.id);
end;
$$;


--
-- Name: log_npr_episodes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.log_npr_episodes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    program_id uuid NOT NULL,
    show_date date NOT NULL,
    npr_collection_id integer NOT NULL,
    status public.log_npr_episode_status NOT NULL,
    npr_episode_id text,
    title text,
    raw jsonb,
    retrieved_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT log_npr_episodes_found_has_id CHECK ((((status = 'found'::public.log_npr_episode_status) AND (npr_episode_id IS NOT NULL)) OR ((status = 'not_found'::public.log_npr_episode_status) AND (npr_episode_id IS NULL))))
);


--
-- Name: log_replace_npr_episode_cache(uuid, date, integer, public.log_npr_episode_status, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_replace_npr_episode_cache(p_program_id uuid, p_show_date date, p_npr_collection_id integer, p_status public.log_npr_episode_status, p_npr_episode_id text, p_title text, p_raw jsonb, p_items jsonb) RETURNS public.log_npr_episodes
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_episode public.log_npr_episodes;
begin
  delete from public.log_npr_episodes
  where program_id = p_program_id and show_date = p_show_date;
  -- log_npr_episode_items.episode_id is `on delete cascade`, so the old
  -- episode's items are already gone once this delete commits.

  insert into public.log_npr_episodes
    (program_id, show_date, npr_collection_id, status, npr_episode_id, title, raw)
  values
    (p_program_id, p_show_date, p_npr_collection_id, p_status, p_npr_episode_id, p_title, p_raw)
  returning * into v_episode;

  if p_items is not null and jsonb_array_length(p_items) > 0 then
    insert into public.log_npr_episode_items
      (episode_id, position, npr_item_id, title, teaser, duration_seconds, raw)
    select
      v_episode.id,
      ordinality,
      item->>'npr_item_id',
      item->>'title',
      item->>'teaser',
      nullif(item->>'duration_seconds', '')::integer,
      item->'raw'
    from jsonb_array_elements(p_items) with ordinality as elems(item, ordinality);
  end if;

  return v_episode;
end;
$$;


--
-- Name: log_search_dad_cuts(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_search_dad_cuts(p_query text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when auth.uid() is null or not (
      private.has_underwriting_access(auth.uid()) or private.has_log_access(auth.uid())
    ) then jsonb_build_object('error', 'forbidden')
    else jsonb_build_object('ok', true, 'cuts', coalesce((
      select jsonb_agg(jsonb_build_object('cut', cut, 'title', title, 'group', dad_group) order by cut)
      from (
        select i.dad_cart_number as cut, i.title, i.dad_group
        from public.log_content_items i
        where i.dad_cart_number is not null
          and (
            nullif(btrim(coalesce(p_query, '')), '') is null
            or i.dad_cart_number ilike '%' || btrim(p_query) || '%'
            or i.title ilike '%' || btrim(p_query) || '%'
          )
        order by i.dad_cart_number
        limit 20
      ) matches
    ), '[]'::jsonb))
  end;
$$;


--
-- Name: log_supersede_rundown(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_supersede_rundown(p_rundown_id uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rundown public.log_rundowns;
  v_item record;
  v_recorded integer := 0;
  v_note text;
begin
  if auth.uid() is null then
    return jsonb_build_object('error', 'unauthenticated');
  end if;
  if not private.is_log_producer(auth.uid()) then
    return jsonb_build_object('error', 'forbidden');
  end if;

  select * into v_rundown from public.log_rundowns where id = p_rundown_id for update;
  if not found then
    return jsonb_build_object('error', 'unknown_rundown');
  end if;
  if v_rundown.superseded_at is not null then
    return jsonb_build_object('error', 'already_superseded');
  end if;
  if v_rundown.status <> 'generated' or v_rundown.shift_start_at <= now() then
    return jsonb_build_object('error', 'rundown_started');
  end if;
  if exists (
    select 1
    from public.log_broadcast_events e
    join public.log_rundown_items i on i.id = e.rundown_item_id
    join public.log_rundown_breaks b on b.id = i.break_id
    where b.rundown_id = p_rundown_id
  ) then
    return jsonb_build_object('error', 'has_events');
  end if;

  v_note := 'Special clock: this rundown was replaced by one on another clock.'
    || case when nullif(btrim(coalesce(p_note, '')), '') is null then '' else ' ' || btrim(p_note) end;

  -- Every credit that was placed here is a credit that will not air as sold.
  -- The miss goes through the ordinary event path, so the existing trigger
  -- raises the exception; Traffic decides on a makegood or a waiver.
  for v_item in
    select i.id
    from public.log_rundown_items i
    join public.log_rundown_breaks b on b.id = i.break_id
    join public.uw_scheduled_placements sp
      on sp.log_rundown_item_id = i.id and sp.status <> 'superseded'
    where b.rundown_id = p_rundown_id and i.item_kind = 'underwriting_credit'
  loop
    insert into public.log_broadcast_events (
      rundown_item_id, outcome, confirmation_source, reason, notes, recorded_by
    ) values (
      v_item.id, 'missed', 'management_correction', 'special_coverage', v_note, auth.uid()
    );
    v_recorded := v_recorded + 1;
  end loop;

  update public.log_rundowns set superseded_at = now() where id = p_rundown_id;

  return jsonb_build_object(
    'ok', true,
    'program_id', v_rundown.program_id,
    'air_date', v_rundown.air_date,
    'credits_recorded', v_recorded
  );
end;
$$;


--
-- Name: log_underwriters_for_copy(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_underwriters_for_copy(p_copy_ids uuid[]) RETURNS TABLE(copy_id uuid, underwriter_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null or not private.has_log_access(auth.uid()) then
    return;
  end if;

  return query
  select
    c.id,
    coalesce(
      du.name,
      (
        select cu.name
        from public.uw_contract_copy cc
        join public.uw_contracts k on k.id = cc.contract_id
        join public.uw_underwriters cu on cu.id = k.underwriter_id
        where cc.copy_id = c.id
        order by k.created_at
        limit 1
      )
    )
  from public.uw_copy c
  left join public.uw_underwriters du on du.id = c.underwriter_id
  where c.id = any (p_copy_ids)
    and exists (
      select 1 from public.log_rundown_items lri
      where lri.underwriting_copy_id = c.id
    );
end;
$$;


--
-- Name: rc_articles_before_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rc_articles_before_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if (new.title, new.body) is distinct from (old.title, old.body) then
    new.version := old.version + 1;
    if new.source = 'editor' then
      new.edited_since_release := true;
    else
      new.edited_since_release := false;
    end if;
  else
    new.version := old.version;
  end if;
  return new;
end;
$$;


--
-- Name: rc_articles_needing_embedding(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rc_articles_needing_embedding(p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, title text, summary text, body_text text, content_hash text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select a.id, a.title, a.summary, public.rc_body_text(a.body), a.content_hash
  from public.rc_articles a
  left join public.rc_article_embeddings e on e.article_id = a.id
  where e.article_id is null or e.content_hash <> a.content_hash
  order by a.updated_at desc
  limit greatest(1, least(coalesce(p_limit, 50), 200));
$$;


--
-- Name: rc_articles_snapshot_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rc_articles_snapshot_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' or new.version <> old.version then
    insert into public.rc_article_versions (article_id, version, title, body, source, note, created_by)
    values (new.id, new.version, new.title, new.body, new.source, new.version_note, auth.uid());
  end if;
  return null;
end;
$$;


--
-- Name: rc_body_text(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rc_body_text(body jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public'
    AS $_$
  select coalesce(string_agg(t #>> '{}', ' '), '')
  from jsonb_path_query(body, 'strict $.**.text') as t
  where jsonb_typeof(t) = 'string';
$_$;


--
-- Name: rc_pinned_procedures_check_kind(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rc_pinned_procedures_check_kind() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if not exists (
    select 1 from public.rc_articles where id = new.article_id and kind = 'procedure'
  ) then
    raise exception 'Only a procedure can be pinned';
  end if;
  return new;
end;
$$;


--
-- Name: rc_search_articles(text, integer, text, extensions.vector); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rc_search_articles(p_query text, p_limit integer DEFAULT 30, p_fallback_query text DEFAULT NULL::text, p_embedding extensions.vector DEFAULT NULL::extensions.vector) RETURNS TABLE(id uuid, rank real)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  with strict_q as (
    select websearch_to_tsquery('english', coalesce(p_query, '')) as ts
  ),
  loose_q as (
    select websearch_to_tsquery('english', coalesce(p_fallback_query, '')) as ts
  ),
  strict_hits as (
    select a.id, ts_rank(a.search_vector, q.ts) as score
    from public.rc_articles a, strict_q q
    where numnode(q.ts) > 0 and a.search_vector @@ q.ts
  ),
  loose_hits as (
    select a.id, ts_rank(a.search_vector, q.ts) as score
    from public.rc_articles a, loose_q q
    where numnode(q.ts) > 0
      and a.search_vector @@ q.ts
      and not exists (select 1 from strict_hits)
  ),
  keyword_ranked as (
    select id, row_number() over (order by score desc, id) as rn
    from (select * from strict_hits union all select * from loose_hits) hits
  ),
  vector_ranked as (
    select id, row_number() over (order by distance, id) as rn
    from (
      select a.id, (e.embedding <=> p_embedding) as distance
      from public.rc_article_embeddings e
      join public.rc_articles a on a.id = e.article_id
      where p_embedding is not null
      order by e.embedding <=> p_embedding
      limit greatest(coalesce(p_limit, 30), 30) * 2
    ) nearest
  ),
  fused as (
    select
      coalesce(k.id, v.id) as id,
      coalesce(1.0 / (60 + k.rn), 0) + coalesce(1.0 / (60 + v.rn), 0) as score
    from keyword_ranked k
    full outer join vector_ranked v on v.id = k.id
  )
  select f.id, f.score::real as rank
  from fused f
  order by f.score desc, f.id
  limit greatest(1, least(coalesce(p_limit, 30), 100));
$$;


--
-- Name: rd_guard_post_curation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rd_guard_post_curation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.author_id is distinct from old.author_id then
    raise exception 'A post''s author cannot be changed.'
      using errcode = 'check_violation';
  end if;

  if (new.status, new.status_note, new.kind, new.tool_id)
       is distinct from (old.status, old.status_note, old.kind, old.tool_id)
     and not (
       private.is_roadmap_curator(auth.uid())
       or private.is_administrator(auth.uid())
     )
  then
    raise exception 'Only a roadmap curator can change a post''s status, kind, or linked tool.'
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


--
-- Name: ri_participants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ri_participants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    session_id uuid NOT NULL,
    display_name text NOT NULL,
    role public.ri_participant_role NOT NULL,
    profile_id uuid,
    guest_user_id uuid,
    join_token text NOT NULL,
    token_expires_at timestamp with time zone,
    revoked_at timestamp with time zone,
    admitted_at timestamp with time zone,
    clock_offset_ms integer,
    storage_prefix text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    waiting_since timestamp with time zone
);


--
-- Name: ri_bind_guest_participant(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ri_bind_guest_participant(p_token text) RETURNS public.ri_participants
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r public.ri_participants;
begin
  if auth.uid() is null then
    return null;
  end if;

  update public.ri_participants
  set guest_user_id = auth.uid()
  where join_token = p_token
    and role = 'guest'
    and revoked_at is null
    and (token_expires_at is null or token_expires_at > now())
  returning * into r;

  return r;
end;
$$;


--
-- Name: ri_guest_join_waiting_room(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ri_guest_join_waiting_room(p_participant_id uuid, p_display_name text DEFAULT NULL::text) RETURNS public.ri_participants
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r public.ri_participants;
begin
  if auth.uid() is null then
    return null;
  end if;

  update public.ri_participants
  set
    display_name = coalesce(nullif(trim(p_display_name), ''), display_name),
    waiting_since = now()
  where id = p_participant_id
    and guest_user_id = auth.uid()
    and revoked_at is null
    and admitted_at is null
  returning * into r;

  return r;
end;
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: station_public_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.station_public_profile() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'display_name', s.display_name,
    'short_name', s.short_name,
    'call_sign', s.call_sign,
    'primary_city', s.primary_city,
    'region', s.region,
    'coverage_area', s.coverage_area,
    'support_email', s.support_email,
    'public_attribution', s.public_attribution,
    'public_notice_text', s.public_notice_text,
    'public_notice_link_label', s.public_notice_link_label,
    'public_notice_link_url', s.public_notice_link_url
  )
  from public.station_settings s
  where s.id;
$$;


--
-- Name: station_settings_check_time_zone(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.station_settings_check_time_zone() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from pg_catalog.pg_timezone_names z where z.name = new.time_zone) then
    raise exception 'Unknown time zone "%". Use an IANA name such as America/Chicago.', new.time_zone;
  end if;
  return new;
end;
$$;


--
-- Name: sw_accept_quote_suggestion(uuid, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sw_accept_quote_suggestion(p_suggestion_id uuid, p_start_ms integer, p_end_ms integer, p_title text, p_text text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  s public.sw_quote_suggestions%rowtype;
  v_excerpt_id uuid;
begin
  select * into s from public.sw_quote_suggestions where id = p_suggestion_id for update;
  if not found or s.status <> 'suggested' then
    return null;
  end if;

  insert into public.sw_source_excerpts (
    source_id, representation_id, title, start_ms, end_ms, excerpt_text,
    created_by, origin, suggestion_reason
  )
  values (
    s.source_id, s.representation_id, p_title, p_start_ms, p_end_ms, p_text,
    auth.uid(), 'suggested', s.reason
  )
  returning id into v_excerpt_id;

  insert into public.sw_data_point_excerpts (data_point_id, excerpt_id)
  select sp.data_point_id, v_excerpt_id
    from public.sw_quote_suggestion_points sp
   where sp.suggestion_id = s.id
  on conflict do nothing;

  update public.sw_quote_suggestions
     set status = 'accepted', excerpt_id = v_excerpt_id,
         decided_by = auth.uid(), decided_at = now()
   where id = s.id;

  return v_excerpt_id;
end;
$$;


--
-- Name: sw_excerpt_speakers(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sw_excerpt_speakers(p_excerpt_ids uuid[]) RETURNS TABLE(excerpt_id uuid, diarization_label text, display_name text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select e.id, sp.diarization_label, sp.display_name
    from public.sw_source_excerpts e
    cross join lateral (
      select s.speaker_id
        from public.tw_segments s
       where s.representation_id = e.representation_id
         and s.start_ms <= e.start_ms
         and s.end_ms > e.start_ms
       order by s.position
       limit 1
    ) seg
    join public.tw_speakers sp on sp.id = seg.speaker_id
   where e.id = any (p_excerpt_ids)
$$;


--
-- Name: sw_extraction_accept_rates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sw_extraction_accept_rates() RETURNS TABLE(prompt_version_id uuid, accepted integer, rejected integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select
    d.prompt_version_id,
    (count(*) filter (where d.status = 'accepted'))::integer,
    (count(*) filter (where d.status = 'rejected'))::integer
  from public.sw_data_points d
  where d.status <> 'suggested'
  group by d.prompt_version_id
$$;


