-- Name: sw_flag_source_excerpt_embedding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sw_flag_source_excerpt_embedding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.embedding_stale := true;
  return new;
end;
$$;


--
-- Name: sw_publish_piece_format(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sw_publish_piece_format(p_format_id uuid, p_spec jsonb, p_note text) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_next integer;
  v_id uuid;
begin
  perform pg_advisory_xact_lock(hashtext('sw_piece_format_' || p_format_id::text));

  select coalesce(max(version), 0) + 1 into v_next
    from public.sw_piece_format_versions
   where format_id = p_format_id;

  insert into public.sw_piece_format_versions (format_id, version, spec, note, created_by)
  values (p_format_id, v_next, p_spec, nullif(btrim(p_note), ''), auth.uid())
  returning id into v_id;

  update public.sw_piece_formats
     set live_version_id = v_id,
         live_moved_by = auth.uid(),
         live_moved_at = now()
   where id = p_format_id;
  if not found then
    raise exception 'format_not_found' using errcode = 'P0002';
  end if;

  return v_next;
end;
$$;


--
-- Name: sw_publish_prompt(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sw_publish_prompt(p_slot text, p_body text, p_note text) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_next integer;
  v_id uuid;
begin
  -- Serialise publishers of one slot so two editors can't mint the same number.
  perform pg_advisory_xact_lock(hashtext('sw_prompt_' || p_slot));

  select coalesce(max(version), 0) + 1 into v_next
    from public.sw_prompt_versions
   where slot = p_slot;

  insert into public.sw_prompt_versions (slot, version, body, note, created_by)
  values (p_slot, v_next, p_body, nullif(btrim(p_note), ''), auth.uid())
  returning id into v_id;

  insert into public.sw_prompt_live (slot, version_id, moved_by)
  values (p_slot, v_id, auth.uid())
  on conflict (slot) do update
    set version_id = excluded.version_id,
        moved_by = excluded.moved_by,
        moved_at = now();

  return v_next;
end;
$$;


--
-- Name: sw_save_piece_version(uuid, integer, jsonb, text, integer, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sw_save_piece_version(p_piece_id uuid, p_base_version integer, p_body jsonb, p_saved_via text, p_length_seconds integer, p_excerpt_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_current integer;
  v_next integer;
begin
  select current_version into v_current
    from public.sw_pieces
   where id = p_piece_id
   for update;

  if not found then
    raise exception 'piece_not_found' using errcode = 'P0002';
  end if;

  if v_current <> p_base_version then
    return -1;
  end if;

  v_next := v_current + 1;

  insert into public.sw_piece_versions (piece_id, version, body, saved_by, saved_via)
  values (p_piece_id, v_next, p_body, auth.uid(), p_saved_via);

  update public.sw_pieces
     set current_version = v_next,
         length_seconds = greatest(p_length_seconds, 0),
         excerpt_ids = coalesce(p_excerpt_ids, '{}')
   where id = p_piece_id;

  return v_next;
end;
$$;


--
-- Name: sw_save_project_synthesis(uuid, integer, jsonb, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sw_save_project_synthesis(p_project_id uuid, p_base_version integer, p_body jsonb, p_saved_via text, p_run_id uuid, p_prompt_version_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_current integer;
  v_next integer;
begin
  insert into public.sw_project_syntheses (project_id) values (p_project_id)
    on conflict (project_id) do nothing;

  select current_version into v_current
    from public.sw_project_syntheses
   where project_id = p_project_id
   for update;

  if v_current <> p_base_version then
    return -1;
  end if;

  v_next := v_current + 1;

  insert into public.sw_project_synthesis_versions
    (project_id, version, body, saved_by, saved_via, run_id, prompt_version_id)
  values
    (p_project_id, v_next, p_body, auth.uid(), p_saved_via, p_run_id, p_prompt_version_id);

  update public.sw_project_syntheses
     set current_version = v_next
   where project_id = p_project_id;

  return v_next;
end;
$$;


--
-- Name: tool_access_sync_roles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tool_access_sync_roles() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    if cardinality(new.tool_roles) = 0 and nullif(btrim(coalesce(new.tool_role, '')), '') is not null then
      new.tool_roles := array[lower(btrim(new.tool_role))];
    end if;
  elsif new.tool_roles is not distinct from old.tool_roles
        and new.tool_role is distinct from old.tool_role then
    new.tool_roles := case
      when nullif(btrim(coalesce(new.tool_role, '')), '') is null then '{}'::text[]
      else array[lower(btrim(new.tool_role))] end;
  end if;
  new.tool_roles := array(
    select distinct lower(btrim(r)) from unnest(new.tool_roles) as r where btrim(r) <> ''
    order by 1
  );
  new.tool_role := new.tool_roles[1];
  return new;
end;
$$;


--
-- Name: tw_flag_chunks_for_project(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tw_flag_chunks_for_project() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  update public.tw_chunks
     set stale = true
   where representation_id in (
     select r.id
       from public.sw_representations r
       join public.sw_project_sources ps on ps.source_id = r.source_id
      where ps.project_id = new.id
        and r.kind = 'transcript'
   );
  return null;
end;
$$;


--
-- Name: tw_flag_chunks_for_segment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tw_flag_chunks_for_segment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  update public.tw_chunks
     set stale = true
   where representation_id = coalesce(new.representation_id, old.representation_id)
     and start_ms <= coalesce(new.end_ms, old.end_ms)
     and end_ms >= coalesce(new.start_ms, old.start_ms);
  return null;
end;
$$;


