--
-- Name: tw_search(text, extensions.vector, integer, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tw_search(query_text text, query_embedding extensions.vector DEFAULT NULL::extensions.vector, match_limit integer DEFAULT 30, project_id_filter uuid DEFAULT NULL::uuid, source_id_filter uuid DEFAULT NULL::uuid) RETURNS TABLE(kind text, result_id uuid, project_id uuid, source_id uuid, project_title text, project_description text, interview_date date, start_ms integer, end_ms integer, page_number integer, title text, snippet text, speaker_label text, score real)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  with q as (
    select websearch_to_tsquery('english', coalesce(query_text, '')) as ts
  ),
  keyword as (
    select
      case when r.kind = 'document_text' then 'document' else 'transcript' end as hit_kind,
      ch.id as hit_id,
      ts_rank_cd(ch.search, q.ts) as rank_score
      from public.tw_chunks ch
      join public.sw_representations r on r.id = ch.representation_id, q
     where numnode(q.ts) > 0 and ch.search @@ q.ts
    union all
    select 'clip', ex.id, ts_rank_cd(ex.search, q.ts)
      from public.sw_source_excerpts ex, q
     where numnode(q.ts) > 0 and ex.search @@ q.ts
    union all
    select 'project', p.id, ts_rank_cd(p.search, q.ts)
      from public.tw_projects p, q
     where numnode(q.ts) > 0 and p.search @@ q.ts
  ),
  keyword_ranked as (
    select hit_kind, hit_id, row_number() over (order by rank_score desc, hit_id) as rn
      from keyword
  ),
  vector_hits as (
    select * from (
      select
        case when r.kind = 'document_text' then 'document' else 'transcript' end as hit_kind,
        ch.id as hit_id,
        (ch.embedding <=> query_embedding) as distance
        from public.tw_chunks ch
        join public.sw_representations r on r.id = ch.representation_id
       where query_embedding is not null and ch.embedding is not null
       order by ch.embedding <=> query_embedding
       limit greatest(match_limit, 30) * 2
    ) chunk_hits
    union all
    select * from (
      select 'clip'::text, ex.id, (ex.embedding <=> query_embedding)
        from public.sw_source_excerpts ex
       where query_embedding is not null and ex.embedding is not null
       order by ex.embedding <=> query_embedding
       limit greatest(match_limit, 30) * 2
    ) excerpts
  ),
  vector_ranked as (
    select hit_kind, hit_id, row_number() over (order by distance, hit_id) as rn
      from vector_hits
  ),
  fused as (
    select
      coalesce(k.hit_kind, v.hit_kind) as hit_kind,
      coalesce(k.hit_id, v.hit_id) as hit_id,
      (coalesce(1.0 / (60 + k.rn), 0) + coalesce(1.0 / (60 + v.rn), 0))
        * case when coalesce(k.hit_kind, v.hit_kind) = 'clip' then 1.2 else 1.0 end as fused_score
      from keyword_ranked k
      full outer join vector_ranked v on v.hit_kind = k.hit_kind and v.hit_id = k.hit_id
  )
  select
    f.hit_kind as kind,
    f.hit_id as result_id,
    proj.id as project_id,
    coalesce(chunk_src.id, excerpt_src.id) as source_id,
    proj.title as project_title,
    proj.description as project_description,
    coalesce(chunk_src.interview_date, excerpt_src.interview_date) as interview_date,
    coalesce(ch.start_ms, ex.start_ms) as start_ms,
    coalesce(ch.end_ms, ex.end_ms) as end_ms,
    coalesce(ch.page_start, excerpt_loc.page_number) as page_number,
    ex.title,
    coalesce(ch.text, ex.excerpt_text, proj.description, '') as snippet,
    spk.label as speaker_label,
    f.fused_score::real as score
    from fused f
    left join public.tw_chunks ch on f.hit_kind in ('transcript', 'document') and ch.id = f.hit_id
    left join public.sw_source_excerpts ex on f.hit_kind = 'clip' and ex.id = f.hit_id
    left join public.sw_representations chunk_rep
      on f.hit_kind in ('transcript', 'document') and chunk_rep.id = ch.representation_id
    left join public.sw_sources chunk_src on chunk_src.id = chunk_rep.source_id
    left join public.sw_sources excerpt_src on f.hit_kind = 'clip' and excerpt_src.id = ex.source_id
    left join lateral (
      select l.page_number
        from public.sw_excerpt_document_locations l
       where f.hit_kind = 'clip' and l.excerpt_id = ex.id
       order by l.sequence
       limit 1
    ) excerpt_loc on true
    left join lateral (
      select ps.project_id
        from public.sw_project_sources ps
       where ps.source_id = coalesce(chunk_src.id, excerpt_src.id)
         and f.hit_kind in ('transcript', 'document', 'clip')
       order by (ps.project_id = project_id_filter) desc, ps.added_at
       limit 1
    ) referencing_project on true
    join public.tw_projects proj
      on proj.id = case f.hit_kind
                     when 'project' then f.hit_id
                     else referencing_project.project_id
                   end
    left join lateral (
      select coalesce(nullif(trim(sp.display_name), ''), 'Speaker ' || sp.diarization_label) as label
        from public.tw_segments sg
        left join public.tw_speakers sp on sp.id = sg.speaker_id
       where f.hit_kind = 'clip'
         and sg.representation_id = ex.representation_id
         and sg.start_ms <= ex.start_ms
       order by sg.start_ms desc
       limit 1
    ) spk on true
   where (project_id_filter is null or proj.id = project_id_filter)
     and (source_id_filter is null or coalesce(chunk_src.id, excerpt_src.id) = source_id_filter)
   order by f.fused_score desc, proj.created_at desc
   limit match_limit;
$$;


--
-- Name: tw_shift_segment_positions(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tw_shift_segment_positions(p_representation_id uuid, after_position integer, delta integer) RETURNS void
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  update public.tw_segments
  set position = position + delta
  where representation_id = p_representation_id
    and position > after_position;
$$;


--
-- Name: log_rundown_breaks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.log_rundown_breaks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    rundown_id uuid NOT NULL,
    local_opportunity_id uuid,
    "position" integer NOT NULL,
    label text NOT NULL,
    requirement public.log_opportunity_requirement NOT NULL,
    permitted_content_types text[] DEFAULT '{}'::text[] NOT NULL,
    scheduled_at timestamp with time zone NOT NULL,
    available_duration_seconds integer NOT NULL,
    network_rejoin_at timestamp with time zone NOT NULL,
    clock_slot_id uuid NOT NULL,
    hour_index integer NOT NULL,
    landing_offset_seconds integer,
    CONSTRAINT log_rundown_breaks_duration_check CHECK ((available_duration_seconds > 0)),
    CONSTRAINT log_rundown_breaks_hour_index_check CHECK ((hour_index >= 0))
);


--
-- Name: log_rundowns; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.log_rundowns (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    program_id uuid NOT NULL,
    schedule_entry_id uuid,
    clock_version_id uuid NOT NULL,
    air_date date NOT NULL,
    shift_start_at timestamp with time zone NOT NULL,
    shift_end_at timestamp with time zone NOT NULL,
    status public.log_rundown_status DEFAULT 'draft'::public.log_rundown_status NOT NULL,
    generated_at timestamp with time zone,
    submitted_at timestamp with time zone,
    submitted_by uuid,
    source text DEFAULT 'generated'::text NOT NULL,
    superseded_at timestamp with time zone,
    CONSTRAINT log_rundowns_shift_range_check CHECK ((shift_end_at > shift_start_at)),
    CONSTRAINT log_rundowns_source_check CHECK ((source = ANY (ARRAY['generated'::text, 'imported'::text])))
);


--
-- Name: uw_automation_block(public.log_rundown_breaks, public.log_rundowns); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_automation_block(p_break public.log_rundown_breaks, p_rundown public.log_rundowns) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  select case
    when p_rundown.superseded_at is not null then 'rundown_superseded'
    when p_rundown.status in ('in_progress', 'submitted') then 'rundown_frozen'
    when p_break.scheduled_at <= now() then 'break_in_past'
    else null
  end;
$$;


--
-- Name: uw_contract_schedule_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.uw_contract_schedule_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contract_id uuid NOT NULL,
    days_of_week integer[] DEFAULT '{}'::integer[],
    duration_seconds integer NOT NULL,
    program_id uuid,
    start_date date NOT NULL,
    end_date date,
    notes text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    label text DEFAULT ''::text NOT NULL,
    flight_id uuid,
    pool_id uuid,
    window_start time without time zone,
    window_end time without time zone,
    max_per_day integer,
    stated_total integer,
    source_text text,
    status public.uw_schedule_line_status DEFAULT 'active'::public.uw_schedule_line_status NOT NULL,
    cancelled_from date,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    revision_id uuid NOT NULL,
    entry_kind public.uw_schedule_entry_kind NOT NULL,
    entry_spec jsonb DEFAULT '{}'::jsonb NOT NULL,
    time_mode public.uw_time_mode DEFAULT 'any'::public.uw_time_mode NOT NULL,
    preferred_time time without time zone,
    service_level public.uw_service_level DEFAULT 'guaranteed'::public.uw_service_level NOT NULL,
    distribution_preference text,
    makegood_policy_text text,
    CONSTRAINT uw_contract_schedule_lines_cancel_check CHECK (((status = 'active'::public.uw_schedule_line_status) OR ((cancelled_from IS NOT NULL) AND (cancelled_at IS NOT NULL)))),
    CONSTRAINT uw_contract_schedule_lines_date_range_check CHECK (((end_date IS NULL) OR (end_date >= start_date))),
    CONSTRAINT uw_contract_schedule_lines_duration_check CHECK ((duration_seconds > 0)),
    CONSTRAINT uw_contract_schedule_lines_max_per_day_check CHECK (((max_per_day IS NULL) OR (max_per_day >= 1))),
    CONSTRAINT uw_contract_schedule_lines_stated_total_check CHECK (((stated_total IS NULL) OR (stated_total >= 0))),
    CONSTRAINT uw_contract_schedule_lines_target_check CHECK (((pool_id IS NOT NULL) OR (program_id IS NOT NULL))),
    CONSTRAINT uw_contract_schedule_lines_time_mode_check CHECK (
CASE time_mode
    WHEN 'any'::public.uw_time_mode THEN true
    WHEN 'window'::public.uw_time_mode THEN (window_start IS NOT NULL)
    WHEN 'preferred'::public.uw_time_mode THEN (preferred_time IS NOT NULL)
    WHEN 'exact'::public.uw_time_mode THEN (preferred_time IS NOT NULL)
    WHEN 'opening'::public.uw_time_mode THEN true
    WHEN 'closing'::public.uw_time_mode THEN true
    ELSE NULL::boolean
END),
    CONSTRAINT uw_contract_schedule_lines_window_order_check CHECK (((window_start IS NULL) OR (window_end > window_start))),
    CONSTRAINT uw_contract_schedule_lines_window_pair_check CHECK (((window_start IS NULL) = (window_end IS NULL)))
);


--
-- Name: uw_break_position_eligible(public.uw_contract_schedule_lines, public.log_rundown_breaks); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_break_position_eligible(p_line public.uw_contract_schedule_lines, p_break public.log_rundown_breaks) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case p_line.time_mode
    when 'opening' then not exists (
      select 1 from public.log_rundown_breaks o
      where o.rundown_id = p_break.rundown_id
        and o.id <> p_break.id
        and o.local_opportunity_id is not null
        and 'underwriting_credit' = any(o.permitted_content_types)
        and o.scheduled_at < p_break.scheduled_at
    )
    when 'closing' then not exists (
      select 1 from public.log_rundown_breaks o
      where o.rundown_id = p_break.rundown_id
        and o.id <> p_break.id
        and o.local_opportunity_id is not null
        and 'underwriting_credit' = any(o.permitted_content_types)
        and o.scheduled_at > p_break.scheduled_at
    )
    else true
  end;
$$;


--
-- Name: uw_demand_buckets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.uw_demand_buckets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    schedule_line_id uuid NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    quantity_required integer NOT NULL,
    status public.uw_demand_bucket_status DEFAULT 'active'::public.uw_demand_bucket_status NOT NULL,
    source_label text,
    superseded_by_revision_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT uw_demand_buckets_period_check CHECK ((period_end >= period_start)),
    CONSTRAINT uw_demand_buckets_quantity_check CHECK ((quantity_required >= 0))
);


--
-- Name: uw_bucket_for_date(public.uw_contract_schedule_lines, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_bucket_for_date(p_line public.uw_contract_schedule_lines, p_date date) RETURNS public.uw_demand_buckets
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_bucket public.uw_demand_buckets;
  v_dow integer := extract(dow from p_date)::integer;
begin
  if p_date < p_line.start_date or (p_line.end_date is not null and p_date > p_line.end_date) then
    return null;
  end if;
  if p_line.status = 'cancelled' and p_line.cancelled_from is not null and p_date >= p_line.cancelled_from then
    return null;
  end if;
  if array_length(p_line.days_of_week, 1) > 0 and not (v_dow = any(p_line.days_of_week)) then
    return null;
  end if;
  select b.* into v_bucket
  from public.uw_demand_buckets b
  where b.schedule_line_id = p_line.id
    and b.status = 'active'
    and b.quantity_required > 0
    and b.period_start <= p_date
    and b.period_end >= p_date
  order by b.period_start
  limit 1;
  if not found then
    return null;
  end if;
  return v_bucket;
end;
$$;


--
-- Name: uw_copy_assign_dad_cut(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_copy_assign_dad_cut() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.dad_cut is null
     and (tg_op = 'INSERT' or old.dad_cut is not null)
     and not private.uw_script_plays_recording(new.script) then
    new.dad_cut := private.uw_next_dad_cut();
  end if;
  return new;
end;
$$;


--
-- Name: uw_copy_dad_recording(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_copy_dad_recording() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_explicit boolean;
begin
  if tg_op = 'INSERT' then
    v_explicit := new.dad_recorded_at is not null;
  else
    v_explicit := new.dad_recorded_at is distinct from old.dad_recorded_at;
  end if;

  if v_explicit and auth.uid() is not null
     and not private.is_underwriting_production(auth.uid()) then
    raise exception 'Only production can mark copy recorded in DAD.'
      using errcode = '42501';
  end if;

  if tg_op = 'UPDATE' and not v_explicit and (
       new.dad_cut is distinct from old.dad_cut
       or (new.dad_cut like '%A' and new.script is distinct from old.script)
     ) then
    new.dad_recorded_at := null;
  end if;

  if new.dad_recorded_at is null then
    new.dad_recorded_by := null;
  elsif v_explicit then
    new.dad_recorded_by := auth.uid();
  end if;
  return new;
end;
$$;


--
-- Name: uw_copy_serves_line(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_copy_serves_line(p_contract_id uuid, p_copy_id uuid, p_line_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_scope uuid;
begin
  select schedule_line_id into v_scope
  from public.uw_contract_copy
  where contract_id = p_contract_id and copy_id = p_copy_id;
  if not found then
    return true;
  end if;
  if v_scope is not null then
    return v_scope = p_line_id;
  end if;
  return not exists (
    select 1 from public.uw_contract_copy
    where contract_id = p_contract_id and schedule_line_id = p_line_id
  );
end;
$$;


--
-- Name: uw_create_inventory_pool(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_create_inventory_pool(p_name text, p_description text, p_targets jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_pool_id uuid;
begin
  if p_name is null or btrim(p_name) = '' then
    raise exception 'A pool needs a name.' using errcode = 'check_violation';
  end if;

  insert into public.uw_inventory_pools (name, description, created_by)
  values (btrim(p_name), nullif(btrim(p_description), ''), auth.uid())
  returning id into v_pool_id;

  if p_targets is not null and jsonb_array_length(p_targets) > 0 then
    insert into public.uw_inventory_pool_targets
      (pool_id, program_id, window_start, window_end, days_of_week, notes)
    select
      v_pool_id,
      nullif(item->>'program_id', '')::uuid,
      nullif(item->>'window_start', '')::time,
      nullif(item->>'window_end', '')::time,
      case
        when item->'days_of_week' is null or jsonb_typeof(item->'days_of_week') <> 'array'
          or jsonb_array_length(item->'days_of_week') = 0
        then null
        else (select array_agg(d::integer order by d::integer)
              from jsonb_array_elements_text(item->'days_of_week') as days(d))
      end,
      nullif(item->>'notes', '')
    from jsonb_array_elements(p_targets) as elems(item);
  end if;

  return v_pool_id;
end;
$$;


--
-- Name: uw_exact_time_tolerance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_exact_time_tolerance() RETURNS interval
    LANGUAGE sql IMMUTABLE
    AS $$ select interval '3 minutes'; $$;


--
-- Name: uw_flag_exception_from_broadcast_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_flag_exception_from_broadcast_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item public.log_rundown_items;
  v_placement public.uw_scheduled_placements;
  v_requires_approval boolean;
begin
  if new.outcome = 'aired_as_scheduled' then
    return new;
  end if;

  select * into v_item from public.log_rundown_items where id = new.rundown_item_id;
  if not found or v_item.item_kind <> 'underwriting_credit' then
    return new;
  end if;

  select * into v_placement
  from public.uw_scheduled_placements
  where log_rundown_item_id = new.rundown_item_id
    and status <> 'superseded'
  order by created_at desc
  limit 1;
  if not found then
    return new;
  end if;

  select c.makegood_requires_agency_approval into v_requires_approval
  from public.uw_contract_schedule_lines sl
  join public.uw_contracts c on c.id = sl.contract_id
  where sl.id = v_placement.schedule_line_id;

  insert into public.uw_exceptions (
    log_broadcast_event_id, schedule_line_id, scheduled_placement_id, original_scheduled_at,
    host_action, host_reason, makegood_approval
  ) values (
    new.id, v_placement.schedule_line_id, v_placement.id, v_placement.scheduled_at,
    new.outcome::text, new.reason::text,
    (case when coalesce(v_requires_approval, false) then 'pending' else 'not_required' end)::public.uw_makegood_approval
  )
  on conflict (log_broadcast_event_id) do nothing;

  return new;
end;
$$;


--
-- Name: uw_guard_affidavit_certification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_guard_affidavit_certification() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if old.status = 'certified' then
    if new.status is distinct from old.status
       or new.contract_id is distinct from old.contract_id
       or new.campaign_period_start is distinct from old.campaign_period_start
       or new.campaign_period_end is distinct from old.campaign_period_end
       or new.report_identifier is distinct from old.report_identifier
       -- Only the foreign key's own on-delete-set-null may clear the certifier.
       or (new.certifying_staff_id is distinct from old.certifying_staff_id
           and new.certifying_staff_id is not null)
       or new.certifying_staff_title is distinct from old.certifying_staff_title
       or new.certification_text is distinct from old.certification_text
       or new.certified_at is distinct from old.certified_at
       or new.certified_document_path is distinct from old.certified_document_path
       or new.certified_document_sha256 is distinct from old.certified_document_sha256
    then
      raise exception 'A certified affidavit cannot be changed. Generate a new one instead.'
        using errcode = 'check_violation';
    end if;
    return new;
  end if;

  if new.status = 'certified'
     and not (select private.is_underwriting_manager((select auth.uid())))
  then
    raise exception 'Only an underwriting manager can certify an affidavit.'
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


--
-- Name: uw_guard_bucket_overlap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_guard_bucket_overlap() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.status = 'active' and exists (
    select 1 from public.uw_demand_buckets b
    where b.schedule_line_id = new.schedule_line_id
      and b.id <> new.id
      and b.status = 'active'
      and b.period_start <= new.period_end
      and b.period_end >= new.period_start
  ) then
    raise exception 'demand bucket % overlaps another active bucket of the same schedule line', new.id
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


--
-- Name: uw_guard_contract_copy_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_guard_contract_copy_line() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.schedule_line_id is null then
    return new;
  end if;
  if not exists (
    select 1 from public.uw_contract_schedule_lines
    where id = new.schedule_line_id and contract_id = new.contract_id
  ) then
    raise exception 'copy_line_other_contract'
      using hint = 'A message can only be dedicated to a line of the contract it is linked to.';
  end if;
  return new;
end;
$$;


--
-- Name: uw_guard_exception_resolution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_guard_exception_resolution() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.resolution_action = 'waive'
     and old.resolution_action is distinct from 'waive'
     and not private.is_underwriting_manager(auth.uid())
  then
    raise exception 'Only an underwriting manager can waive an exception.'
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


--
-- Name: uw_guard_placement_copy_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_guard_placement_copy_line() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_contract uuid;
begin
  if new.status = 'superseded' then
    return new;
  end if;
  if tg_op = 'UPDATE'
     and new.copy_id is not distinct from old.copy_id
     and new.schedule_line_id is not distinct from old.schedule_line_id then
    return new;
  end if;
  select contract_id into v_contract
  from public.uw_contract_schedule_lines where id = new.schedule_line_id;
  if v_contract is not null
     and not public.uw_copy_serves_line(v_contract, new.copy_id, new.schedule_line_id) then
    raise exception 'copy_wrong_line'
      using hint = 'That message is dedicated to another line, or this line has messages of its own.';
  end if;
  return new;
end;
$$;


--
-- Name: uw_guard_placement_dad_cut(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_guard_placement_dad_cut() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'superseded' then
    return new;
  end if;
  if tg_op = 'UPDATE'
     and new.copy_id is not distinct from old.copy_id
     and new.scheduled_at is not distinct from old.scheduled_at then
    return new;
  end if;
  if private.log_is_automated(new.scheduled_at)
     and (select dad_cut from public.uw_copy where id = new.copy_id) is null then
    raise exception 'copy_needs_dad_cut'
      using hint = 'This break is in automated hours, and the message has no DAD cut for DAD to play.';
  end if;
  return new;
end;
$$;


--
-- Name: uw_has_open_exceptions_for_rundown(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_has_open_exceptions_for_rundown(p_rundown_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select private.has_log_access(auth.uid()) and exists (
    select 1
    from public.uw_exceptions ex
    join public.log_broadcast_events lbe on lbe.id = ex.log_broadcast_event_id
    join public.log_rundown_items lri on lri.id = lbe.rundown_item_id
    join public.log_rundown_breaks lrb on lrb.id = lri.break_id
    where lrb.rundown_id = p_rundown_id
      and ex.resolution_status = 'open'
  );
$$;


--
-- Name: uw_pool_matches(uuid, uuid, time without time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_pool_matches(p_pool_id uuid, p_program_id uuid, p_local_time time without time zone, p_dow integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.uw_inventory_pool_targets t
    where t.pool_id = p_pool_id
      and (t.program_id is null or t.program_id = p_program_id)
      and (t.window_start is null or (p_local_time >= t.window_start and p_local_time < t.window_end))
      and (t.days_of_week is null or p_dow = any(t.days_of_week))
  );
$$;


--
-- Name: uw_resolve_exception_when_makegoods_aired(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_resolve_exception_when_makegoods_aired() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status <> 'aired' or old.status = 'aired' then
    return new;
  end if;

  if exists (
    select 1
    from public.uw_makegoods m
    where m.exception_id = new.exception_id
      and m.id <> new.id
      and m.status = 'scheduled'
  ) then
    return new;
  end if;

  update public.uw_exceptions
  set resolution_status = 'resolved',
      resolution_action = coalesce(resolution_action, 'schedule_makegood'),
      resolved_at = now(),
      resolved_by = null,
      resolution_notes = concat_ws(
        E'\n',
        nullif(resolution_notes, ''),
        'Resolved automatically when its makegood aired.'
      )
  where id = new.exception_id
    and resolution_status = 'open';

  return new;
end;
$$;


--
-- Name: uw_station_local_time(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_station_local_time(p_at timestamp with time zone) RETURNS time without time zone
    LANGUAGE sql STABLE
    AS $$
  select (p_at at time zone private.station_time_zone())::time;
$$;


--
-- Name: uw_station_today(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_station_today() RETURNS date
    LANGUAGE sql STABLE
    AS $$
  select (now() at time zone private.station_time_zone())::date;
$$;


--
-- Name: uw_time_eligible(public.uw_contract_schedule_lines, time without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_time_eligible(p_line public.uw_contract_schedule_lines, p_local_time time without time zone) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_line.time_mode
    when 'any' then true
    when 'preferred' then true
    when 'opening' then true
    when 'closing' then true
    when 'window' then p_local_time >= p_line.window_start and p_local_time < p_line.window_end
    when 'exact' then abs(extract(epoch from (p_local_time - p_line.preferred_time))) <= extract(epoch from public.uw_exact_time_tolerance())
  end;
$$;


--
-- Name: uw_update_makegood_from_broadcast_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uw_update_makegood_from_broadcast_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_placement_id uuid;
begin
  if new.outcome <> 'aired_as_scheduled' then
    return new;
  end if;

  select sp.id into v_placement_id
  from public.uw_scheduled_placements sp
  where sp.log_rundown_item_id = new.rundown_item_id
    and sp.status <> 'superseded'
  order by sp.created_at desc
  limit 1;

  if v_placement_id is null then
    return new;
  end if;

  update public.uw_makegoods
  set status = 'aired',
      aired_log_broadcast_event_id = new.id
  where scheduled_placement_id = v_placement_id
    and status = 'scheduled';

  return new;
end;
$$;


