);


--
-- Name: log_rundown_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.log_rundown_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    break_id uuid NOT NULL,
    "position" integer NOT NULL,
    item_kind text DEFAULT 'content'::text NOT NULL,
    content_item_id uuid,
    live_read_title text,
    live_read_script text,
    override_script text,
    override_duration_seconds integer,
    override_live_intro_seconds integer,
    override_live_outro_seconds integer,
    override_tag_seconds integer,
    override_notes text,
    planned_duration_seconds integer NOT NULL,
    placement_status text DEFAULT 'editable'::text NOT NULL,
    underwriting_copy_id uuid,
    source_npr_item_id text,
    source_npr_item_title text,
    dad_spot_number bigint,
    CONSTRAINT log_rundown_items_duration_check CHECK ((planned_duration_seconds > 0)),
    CONSTRAINT log_rundown_items_item_kind_check CHECK ((item_kind = ANY (ARRAY['content'::text, 'live_read'::text, 'weather'::text, 'underwriting_credit'::text]))),
    CONSTRAINT log_rundown_items_item_kind_shape_check CHECK ((((item_kind = 'content'::text) AND (content_item_id IS NOT NULL) AND (live_read_title IS NULL) AND (underwriting_copy_id IS NULL)) OR ((item_kind = 'live_read'::text) AND (content_item_id IS NULL) AND (live_read_title IS NOT NULL) AND (underwriting_copy_id IS NULL)) OR ((item_kind = 'weather'::text) AND (content_item_id IS NULL) AND (live_read_title IS NULL) AND (underwriting_copy_id IS NULL)) OR ((item_kind = 'underwriting_credit'::text) AND (content_item_id IS NULL) AND (live_read_title IS NULL) AND (underwriting_copy_id IS NOT NULL)))),
    CONSTRAINT log_rundown_items_npr_source_check CHECK (((source_npr_item_id IS NULL) OR (item_kind = 'live_read'::text))),
    CONSTRAINT log_rundown_items_override_duration_check CHECK (((override_duration_seconds IS NULL) OR (override_duration_seconds > 0))),
    CONSTRAINT log_rundown_items_placement_status_check CHECK ((placement_status = ANY (ARRAY['locked'::text, 'movable'::text, 'replaceable'::text, 'editable'::text])))
);


