--
-- Name: rc_articles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.rc_articles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    kind public.rc_kind NOT NULL,
    title text NOT NULL,
    summary text,
    body jsonb DEFAULT '{"type": "doc", "content": []}'::jsonb NOT NULL,
    area text,
    owner_role text,
    tool_id uuid,
    screen_keys text[] DEFAULT '{}'::text[] NOT NULL,
    released_on date,
    sort_order integer DEFAULT 0 NOT NULL,
    source public.rc_source DEFAULT 'editor'::public.rc_source NOT NULL,
    version_note text,
    needs_review boolean DEFAULT false NOT NULL,
    edited_since_release boolean DEFAULT false NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    search_vector tsvector GENERATED ALWAYS AS (((setweight(to_tsvector('english'::regconfig, COALESCE(title, ''::text)), 'A'::"char") || setweight(to_tsvector('english'::regconfig, COALESCE(summary, ''::text)), 'B'::"char")) || setweight(to_tsvector('english'::regconfig, public.rc_body_text(body)), 'C'::"char"))) STORED,
    content_hash text GENERATED ALWAYS AS (md5(((((COALESCE(title, ''::text) || '
'::text) || COALESCE(summary, ''::text)) || '
'::text) || public.rc_body_text(body)))) STORED,
    CONSTRAINT rc_articles_guide_shape CHECK (((kind <> 'guide'::public.rc_kind) OR ((tool_id IS NOT NULL) AND (released_on IS NULL)))),
    CONSTRAINT rc_articles_procedure_shape CHECK (((kind <> 'procedure'::public.rc_kind) OR ((area IS NOT NULL) AND (tool_id IS NULL) AND (released_on IS NULL)))),
    CONSTRAINT rc_articles_release_note_shape CHECK (((kind <> 'release_note'::public.rc_kind) OR (released_on IS NOT NULL))),
    CONSTRAINT rc_articles_slug_shape CHECK ((slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text)),
    CONSTRAINT rc_articles_title_present CHECK ((length(TRIM(BOTH FROM title)) > 0))
);


