--
-- Name: station_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.station_settings (
    id boolean DEFAULT true NOT NULL,
    time_zone text DEFAULT 'America/Chicago'::text NOT NULL,
    display_name text,
    short_name text,
    call_sign text,
    licensee text,
    mailing_address text,
    primary_city text,
    region text,
    support_email text,
    public_attribution text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    coverage_area text,
    public_notice_text text,
    public_notice_link_label text,
    public_notice_link_url text,
    latitude numeric(8,5),
    longitude numeric(8,5),
    alert_counties text,
    CONSTRAINT station_settings_alert_counties_check CHECK (((char_length(alert_counties) <= 1000) AND (alert_counties ~ '^[^:\n]+:[0-9]{6}(\n[^:\n]+:[0-9]{6})*$'::text))),
    CONSTRAINT station_settings_call_sign_check CHECK ((char_length(call_sign) <= 40)),
    CONSTRAINT station_settings_coverage_area_check CHECK ((char_length(coverage_area) <= 160)),
    CONSTRAINT station_settings_display_name_check CHECK ((char_length(display_name) <= 120)),
    CONSTRAINT station_settings_id_check CHECK (id),
    CONSTRAINT station_settings_latitude_check CHECK (((latitude >= ('-90'::integer)::numeric) AND (latitude <= (90)::numeric))),
    CONSTRAINT station_settings_licensee_check CHECK ((char_length(licensee) <= 160)),
    CONSTRAINT station_settings_location_pair CHECK (((latitude IS NULL) = (longitude IS NULL))),
    CONSTRAINT station_settings_longitude_check CHECK (((longitude >= ('-180'::integer)::numeric) AND (longitude <= (180)::numeric))),
    CONSTRAINT station_settings_mailing_address_check CHECK ((char_length(mailing_address) <= 400)),
    CONSTRAINT station_settings_primary_city_check CHECK ((char_length(primary_city) <= 80)),
    CONSTRAINT station_settings_public_attribution_check CHECK ((char_length(public_attribution) <= 200)),
    CONSTRAINT station_settings_public_notice_link_label_check CHECK ((char_length(public_notice_link_label) <= 160)),
    CONSTRAINT station_settings_public_notice_link_url_check CHECK (((char_length(public_notice_link_url) <= 300) AND (public_notice_link_url ~ '^(/|https://)'::text))),
    CONSTRAINT station_settings_public_notice_text_check CHECK ((char_length(public_notice_text) <= 300)),
    CONSTRAINT station_settings_region_check CHECK ((char_length(region) <= 80)),
    CONSTRAINT station_settings_short_name_check CHECK ((char_length(short_name) <= 40)),
    CONSTRAINT station_settings_support_email_check CHECK ((char_length(support_email) <= 200))
);


