);


--
-- Name: sw_data_point_counts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.sw_data_point_counts WITH (security_invoker='true') AS
 SELECT d.project_id,
    d.source_id,
    (count(*) FILTER (WHERE (d.status <> 'rejected'::text)))::integer AS total,
    (count(*) FILTER (WHERE (d.status = 'suggested'::text)))::integer AS to_review,
    (count(*) FILTER (WHERE (d.status = 'accepted'::text)))::integer AS accepted,
    (count(*) FILTER (WHERE (d.status = 'rejected'::text)))::integer AS rejected
   FROM (public.sw_data_points d
     JOIN public.sw_project_sources ps ON (((ps.project_id = d.project_id) AND (ps.source_id = d.source_id))))
  GROUP BY d.project_id, d.source_id;


--
-- Name: sw_data_point_excerpts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sw_data_point_excerpts (
    data_point_id uuid NOT NULL,
    excerpt_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: sw_data_point_question_counts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.sw_data_point_question_counts WITH (security_invoker='true') AS
 SELECT d.project_id,
    d.question_id,
    (count(*) FILTER (WHERE (d.status <> 'rejected'::text)))::integer AS total
   FROM (public.sw_data_points d
     JOIN public.sw_project_sources ps ON (((ps.project_id = d.project_id) AND (ps.source_id = d.source_id))))
  WHERE (d.question_id IS NOT NULL)
  GROUP BY d.project_id, d.question_id;


--
-- Name: sw_data_point_spans; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sw_data_point_spans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    data_point_id uuid NOT NULL,
    "position" integer NOT NULL,
    locator_kind text NOT NULL,
    start_ms integer,
    end_ms integer,
    page_number integer,
    first_block_id uuid,
    last_block_id uuid,
    CONSTRAINT sw_data_point_spans_locator_check CHECK ((((locator_kind = 'temporal'::text) AND (start_ms IS NOT NULL) AND (end_ms IS NOT NULL) AND (end_ms > start_ms) AND (start_ms >= 0) AND (page_number IS NULL)) OR ((locator_kind = 'document'::text) AND (page_number IS NOT NULL) AND (page_number >= 1) AND (start_ms IS NULL) AND (end_ms IS NULL)))),
    CONSTRAINT sw_data_point_spans_locator_kind_check CHECK ((locator_kind = ANY (ARRAY['temporal'::text, 'document'::text]))),
    CONSTRAINT sw_data_point_spans_position_check CHECK (("position" >= 0))
);


--
-- Name: sw_document_blocks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sw_document_blocks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    representation_id uuid NOT NULL,
    page_id uuid NOT NULL,
