--
-- Name: sw_project_overview; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.sw_project_overview WITH (security_invoker='true') AS
 SELECT p.id,
    p.title,
    p.description,
    p.created_at,
    p.created_by,
    pr.display_name AS started_by_name,
    COALESCE(src.source_count, 0) AS source_count,
    COALESCE(src.failed_count, 0) AS failed_count,
    COALESCE(src.active_count, 0) AS active_count,
    COALESCE(exc.excerpt_count, 0) AS excerpt_count,
    GREATEST(p.updated_at, src.last_source_at, exc.last_excerpt_at) AS last_activity,
    COALESCE(rev.review_count, 0) AS review_count,
    COALESCE(src.ready_count, 0) AS ready_count,
    COALESCE(src.analyzed_count, 0) AS analyzed_count,
    COALESCE(rev.clip_review_count, 0) AS clip_review_count,
    COALESCE(rev.accepted_count, 0) AS accepted_count,
    COALESCE(syn.has_synthesis, false) AS has_synthesis,
    COALESCE(pc.piece_count, 0) AS piece_count
   FROM ((((((public.tw_projects p
     LEFT JOIN public.profiles pr ON ((pr.id = p.created_by)))
     LEFT JOIN LATERAL ( SELECT (count(DISTINCT s.id))::integer AS source_count,
            (count(DISTINCT s.id) FILTER (WHERE ((s.status = 'failed'::public.sw_source_status) OR (r.status = 'failed'::public.sw_representation_status))))::integer AS failed_count,
            (count(DISTINCT s.id) FILTER (WHERE ((s.status = 'uploading'::public.sw_source_status) OR ((s.status = 'ready'::public.sw_source_status) AND (r.status = ANY (ARRAY['pending'::public.sw_representation_status, 'processing'::public.sw_representation_status]))))))::integer AS active_count,
            max(s.created_at) AS last_source_at,
            (count(DISTINCT s.id) FILTER (WHERE ((s.status = 'ready'::public.sw_source_status) AND (r.status = 'ready'::public.sw_representation_status))))::integer AS ready_count,
            (count(DISTINCT s.id) FILTER (WHERE (( SELECT ar.status
                   FROM public.sw_analysis_runs ar
                  WHERE ((ar.project_id = p.id) AND (ar.source_id = s.id) AND (ar.kind = 'analyze'::text) AND (NOT ar.trial))
                  ORDER BY ar.started_at DESC
                 LIMIT 1) = 'succeeded'::text)))::integer AS analyzed_count
           FROM ((public.sw_project_sources ps
             JOIN public.sw_sources s ON ((s.id = ps.source_id)))
             LEFT JOIN public.sw_representations r ON (((r.source_id = s.id) AND (r.kind = ANY (ARRAY['transcript'::public.sw_representation_kind, 'document_text'::public.sw_representation_kind])))))
          WHERE (ps.project_id = p.id)) src ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS excerpt_count,
            max(e.created_at) AS last_excerpt_at
           FROM public.sw_source_excerpts e
          WHERE (e.source_id IN ( SELECT ps2.source_id
                   FROM public.sw_project_sources ps2
                  WHERE (ps2.project_id = p.id)))) exc ON (true))
     LEFT JOIN LATERAL ( SELECT (( SELECT count(*) AS count
                   FROM (public.sw_data_points d
                     JOIN public.sw_project_sources ps3 ON (((ps3.project_id = d.project_id) AND (ps3.source_id = d.source_id))))
                  WHERE ((d.project_id = p.id) AND (d.status = 'suggested'::text))))::integer AS review_count,
            (( SELECT count(*) AS count
                   FROM (public.sw_quote_suggestions q
                     JOIN public.sw_project_sources ps4 ON (((ps4.project_id = q.project_id) AND (ps4.source_id = q.source_id))))
                  WHERE ((q.project_id = p.id) AND (q.status = 'suggested'::text))))::integer AS clip_review_count,
            (( SELECT count(*) AS count
                   FROM (public.sw_data_points d2
                     JOIN public.sw_project_sources ps5 ON (((ps5.project_id = d2.project_id) AND (ps5.source_id = d2.source_id))))
                  WHERE ((d2.project_id = p.id) AND (d2.status = 'accepted'::text))))::integer AS accepted_count) rev ON (true))
     LEFT JOIN LATERAL ( SELECT (s2.current_version >= 1) AS has_synthesis
           FROM public.sw_project_syntheses s2
          WHERE (s2.project_id = p.id)) syn ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS piece_count
           FROM public.sw_pieces pc2
          WHERE (pc2.project_id = p.id)) pc ON (true));


