    notes text,
    status public.uw_agreement_migration_status DEFAULT 'pending'::public.uw_agreement_migration_status NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    contract_id uuid,
    document_sha256 text,
    last_error text,
    result jsonb,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT uw_agreement_migration_items_dates CHECK (((effective_to IS NULL) OR (effective_from IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT uw_agreement_migration_items_underwriter CHECK (((underwriter_name IS NOT NULL) OR (source_key ~~ 'sha256:%'::text)))
);


--
-- Name: uw_contract_copy; Type: TABLE; Schema: public; Owner: -
