    copy_id uuid NOT NULL,
    flight_id uuid,
    schedule_line_id uuid,
    weight integer DEFAULT 1 NOT NULL,
    CONSTRAINT uw_contract_copy_one_scope CHECK (((flight_id IS NULL) OR (schedule_line_id IS NULL))),
    CONSTRAINT uw_contract_copy_weight_range CHECK (((weight >= 1) AND (weight <= 20)))
);


