    start_date date NOT NULL,
    end_date date NOT NULL,
    status public.uw_flight_status DEFAULT 'active'::public.uw_flight_status NOT NULL,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    notes text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT uw_contract_flights_cancel_check CHECK (((status = 'active'::public.uw_flight_status) OR (cancelled_at IS NOT NULL))),
    CONSTRAINT uw_contract_flights_date_range_check CHECK ((end_date >= start_date))
);


