--
-- Name: uw_contracts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.uw_contracts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contract_identifier text,
    effective_from date NOT NULL,
    effective_to date,
    status public.uw_contract_status DEFAULT 'draft'::public.uw_contract_status NOT NULL,
    notes text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    underwriter_id uuid NOT NULL,
    agreement_document_path text,
    affidavit_required boolean DEFAULT false NOT NULL,
    sponsorship_category text,
    sponsorship_total numeric(10,2),
    preemption_policy text,
    stated_total_spots integer,
    makegood_requires_agency_approval boolean DEFAULT false NOT NULL,
    separation_source_text text,
    separation_policy public.uw_separation_policy DEFAULT 'unspecified'::public.uw_separation_policy NOT NULL,
    separation_minutes integer,
    agreement_reading jsonb,
    account_rep text,
    import_source_key text,
    CONSTRAINT uw_contracts_effective_range_check CHECK (((effective_to IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT uw_contracts_separation_minutes_check CHECK (((separation_policy = 'min_minutes'::public.uw_separation_policy) = (separation_minutes IS NOT NULL))),
    CONSTRAINT uw_contracts_separation_minutes_positive_check CHECK (((separation_minutes IS NULL) OR (separation_minutes > 0))),
    CONSTRAINT uw_contracts_stated_total_check CHECK (((stated_total_spots IS NULL) OR (stated_total_spots >= 0)))
);


