    effective_from date DEFAULT CURRENT_DATE NOT NULL,
    effective_to date,
    approval_status public.uw_copy_approval_status DEFAULT 'draft'::public.uw_copy_approval_status NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    execution_kind public.uw_copy_execution_kind DEFAULT 'live_read'::public.uw_copy_execution_kind NOT NULL,
    label text DEFAULT ''::text NOT NULL,
    underwriter_id uuid,
    dad_cut text,
    dad_recorded_at timestamp with time zone,
    dad_recorded_by uuid,
    CONSTRAINT uw_copy_dad_cut_format CHECK ((dad_cut ~ '^[0-9]{5}A?$'::text)),
    CONSTRAINT uw_copy_duration_check CHECK (((duration_seconds IS NULL) OR (duration_seconds > 0))),
    CONSTRAINT uw_copy_effective_range_check CHECK (((effective_to IS NULL) OR (effective_to >= effective_from)))
);


