CREATE POLICY uw_contract_schedule_lines_delete_draft ON public.uw_contract_schedule_lines FOR DELETE TO authenticated USING ((( SELECT private.has_underwriting_access(( SELECT auth.uid() AS uid)) AS has_underwriting_access) AND ((EXISTS ( SELECT 1
   FROM public.uw_contract_revisions r
  WHERE ((r.id = uw_contract_schedule_lines.revision_id) AND (r.status = 'draft'::public.uw_revision_status)))) OR (EXISTS ( SELECT 1
